    agentCache.value = agents;
  } catch (err) {
    error.value = err instanceof Error ? err.message : t('channelEditor.loadFailed');
  } finally {
    loading.value = false;
  }
}

watch(
  () => props.channelId,
  () => void load(),
  { immediate: false },
);
onMounted(() => void load());
