          content: null,
          reasoning: null,
          toolName: null,
          toolCallId: null,
          toolArguments: null,
          toolResult: null,
          toolDurationMs: null,
          toolErrorCode: null,
          childBoardId: null,
          spiritSessionId: null,
          teamId: null,
          dagNodeId: null,
          dependsOn: null,
          agentKey: null,
          agentName: null,
          collapsed: false,
          label: null,
        },
      ]);

    const promise = tl.loadActivitiesFromAPI('sess-1');
    // Advance through retry delays (500+1000+2000 = 3500ms for 3 failures)
    await vi.advanceTimersByTimeAsync(4000);
    await promise;

    expect(listActivities).toHaveBeenCalledTimes(4);
    expect(tl.loadError.value).toBeNull();
    expect(tl.activities.value).toHaveLength(1);
    expect(tl.activities.value[0].id).toBe('act-1');
    vi.useRealTimers();
  });

  it('retryLoad clears loadError before retrying', async () => {
    vi.useFakeTimers();
    // First, set loadError by failing all retries
    vi.mocked(listActivities).mockRejectedValue(new Error('failure'));

    let promise = tl.loadActivitiesFromAPI('sess-1');
    await vi.advanceTimersByTimeAsync(8000);
    await promise;
    expect(tl.loadError.value).toBeTruthy();

    // Now mock success for retryLoad
    vi.mocked(listActivities).mockResolvedValue([]);

    promise = tl.retryLoad('sess-1');
    await promise;
    expect(tl.loadError.value).toBeNull();
    vi.useRealTimers();
  });
});

import { shallowRef, computed, triggerRef, onUnmounted, getCurrentInstance, type ComputedRef } from 'vue';
import type {
  Activity,
  ActivityStatus,
  ActivityTreeNode,
  ActivityStartMeta,
  ActivityDeltaMeta,
  ActivityDoneMeta,
  ActivityChildStartMeta,
} from '../activityTypes';
import type {
  StreamEvent,
  ThinkingEvent,
  ActionEvent,
  ReplyEvent,
  ErrorEvent,
  PlanEvent,
  PlanStep,
  ConfirmEvent,
  NoticeEvent,
  ToolActivity,
} from '../streamEventTypes';
import { listActivities } from '../../session/api';

/**
 * useActivityTimeline manages Activity state for the Activity-First architecture.
 * It consumes WS activity events (activity_start/delta/done/child_start) and
 * provides computed properties for rendering TaskBoard and other components.
 *
 * This composable replaces the legacy inference-based approach with zero-inference
 * Activity consumption from the backend.
 */
export function useActivityTimeline() {
  const activities = shallowRef<Map<string, Activity>>(new Map());
  const rootActivityId = shallowRef<string | null>(null);
  const loadError = shallowRef<string | null>(null);

  // === Activity tree computed from flat list ===

  const activityTree = computed<ActivityTreeNode[]>(() => {
    const map = new Map<string, ActivityTreeNode>();
    const roots: ActivityTreeNode[] = [];

    // Build tree nodes
    for (const activity of activities.value.values()) {
      map.set(activity.id, { ...activity, children: [] });
    }

    // Link children to parents
    for (const node of map.values()) {
      if (node.parentActivityId && map.has(node.parentActivityId)) {
        map.get(node.parentActivityId)!.children.push(node);
      } else if (!node.parentActivityId) {
        roots.push(node);
      }
    }

    // Sort tree by timestamp to ensure correct order even if WS events arrive out-of-order
    const sortTree = (nodes: ActivityTreeNode[]) => {
      nodes.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
      for (const node of nodes) sortTree(node.children);
    };
    sortTree(roots);

    return roots;
  });

  // === Stream Events (AF → streamEventTypes bridge) ===

  const streamEvents = computed<StreamEvent[]>(() => {
    return activityTree.value
      .filter((node) => node.kind !== 'task' && node.kind !== 'sub_task_board' && node.kind !== 'delegate')
      .map(activityToStreamEvent);
  });

  // === WS Event Handlers ===

  function handleActivityStart(meta: ActivityStartMeta) {
    const activity: Activity = {
      id: meta.activity_id,
      kind: meta.kind,
      status: meta.status,
      sessionId: meta.session_id,
      turnId: meta.turn_id,
      parentActivityId: meta.parent_activity_id || null,
      timestamp: meta.timestamp,
      durationMs: meta.duration_ms || null,
      content: meta.content,
      reasoning: meta.reasoning,
      toolName: meta.tool_name,
      toolCallId: meta.tool_call_id,
      toolArguments: meta.tool_arguments,
      toolResult: meta.tool_result,
      toolDurationMs: meta.tool_duration_ms,
      toolErrorCode: meta.tool_error_code,
      childBoardId: meta.child_board_id,
      spiritSessionId: meta.spirit_session_id,
      teamId: meta.team_id,
      dagNodeId: meta.dag_node_id,
      dependsOn: meta.depends_on,
      agentKey: meta.agent_key,
      agentName: meta.agent_name,
      collapsed: meta.collapsed,
      label: meta.label,
      meta: meta.meta,
    };
    activities.value.set(activity.id, activity);
    triggerRef(activities);

    // Track root activity
    if (!activity.parentActivityId) {
      rootActivityId.value = activity.id;
    }
  }

  function handleActivityDelta(meta: ActivityDeltaMeta) {
    const existing = activities.value.get(meta.activity_id);
    if (!existing) return;

    // Create a new object to ensure reference change for reactivity
    const updated: Activity = { ...existing };
    if (meta.delta_field === 'reasoning') {
      updated.reasoning = (existing.reasoning || '') + meta.delta_chunk;
    } else if (meta.delta_field === 'content') {
      updated.content = (existing.content || '') + meta.delta_chunk;
    }
    activities.value.set(meta.activity_id, updated);
    triggerRef(activities);
  }

  function handleActivityDone(meta: ActivityDoneMeta) {
    const existing = activities.value.get(meta.activity_id);
    if (!existing) return;

    // Create a new object to ensure reference change for reactivity
    const updated: Activity = {
      ...existing,
      status: meta.status as ActivityStatus,
      durationMs: meta.duration_ms,
      collapsed: meta.collapsed,
    };
    if (meta.content !== undefined) updated.content = meta.content;
    if (meta.reasoning !== undefined) updated.reasoning = meta.reasoning;
    if (meta.tool_result !== undefined) updated.toolResult = meta.tool_result;
    if (meta.tool_duration_ms !== undefined) updated.toolDurationMs = meta.tool_duration_ms;
    if (meta.tool_error_code !== undefined) updated.toolErrorCode = meta.tool_error_code;
    if (meta.child_board_id !== undefined) updated.childBoardId = meta.child_board_id;
    if (meta.label !== undefined) updated.label = meta.label;
    activities.value.set(meta.activity_id, updated);
    triggerRef(activities);
  }

  function handleActivityChildStart(meta: ActivityChildStartMeta) {
    const activity: Activity = {
      id: meta.activity_id,
      kind: meta.kind,
      status: meta.status,
      sessionId: '',
      turnId: '',
      parentActivityId: meta.parent_activity_id,
      timestamp: new Date().toISOString(),
      durationMs: null,
      childBoardId: meta.child_board_id,
      teamId: meta.team_id,
      spiritSessionId: meta.spirit_session_id,
      dagNodeId: meta.dag_node_id,
      dependsOn: meta.depends_on,
      collapsed: false,
    };
    activities.value.set(activity.id, activity);
    triggerRef(activities);
  }

  // === Reset (called on turn start) ===

  function reset() {
    activities.value.clear();
    triggerRef(activities);
    rootActivityId.value = null;
  }

  // === Load activities from API (for history recovery) ===

  // AF-FE-15: Coerce numeric fields that the backend may serialize as JSON
  // strings (e.g. `durationMs: "1745"`) into actual numbers. Without this,
  // downstream `sum + (s.durationMs ?? 0)` becomes implicit string
  // concatenation (`1745 + "1588" === "17451588"`), which corrupts
  // displayed durations like "290m 52s".
  function normalizeActivityNumericFields(a: Activity): Activity {
    return {
      ...a,
      durationMs: toNumberOrNull(a.durationMs),
      toolDurationMs: a.toolDurationMs == null ? undefined : (toNumberOrNull(a.toolDurationMs) ?? undefined),
    };
  }

  function toNumberOrNull(v: unknown): number | null {
    if (v == null) return null;
    if (typeof v === 'number' && Number.isFinite(v)) return v;
    if (typeof v === 'string') {
      const trimmed = v.trim();
      if (!trimmed) return null;
      const n = Number(trimmed);
      return Number.isFinite(n) ? n : null;
    }
    return null;
  }

  function loadActivities(activityList: Activity[]) {
    // Atomic replacement: build a complete new Map before assigning to the
    // shallowRef. This avoids the intermediate empty-map state that causes
    // a flash when the old Map is cleared and the new data hasn't been
    // written yet. shallowRef detects the reference change and triggers
    // reactivity exactly once — no manual triggerRef needed.
    const newMap = new Map<string, Activity>();
    let newRootId: string | null = null;
    for (const a of activityList) {
      // AF-FE-15: Backend may return numeric fields as JSON strings (e.g.
      // durationMs="1745"). Coerce them here so downstream reduce/sum/arithmetic
      // never falls into implicit string concatenation (e.g. 1745 + "1588"
      // = "17451588"), which would corrupt displayed durations and turn totals.
      newMap.set(a.id, normalizeActivityNumericFields(a));
      if (!a.parentActivityId) {
        newRootId = a.id;
      }
    }
    activities.value = newMap;
    rootActivityId.value = newRootId;
  }

  // AF-FE-14 / AF-GAP-05: Load activities from backend API for history recovery.
  // Retries up to 5 times with exponential backoff (500ms, 1s, 2s, 4s) on failure.
  // On final failure, sets loadError so the UI can show a "数据加载失败，请刷新"
  // degradation notice instead of silently falling back to Legacy rendering.
  async function loadActivitiesFromAPI(sessionId: string, turnId?: string) {
    const maxAttempts = 5;
    const baseDelay = 500;
    let lastErr: unknown;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      try {
        const activityList = await listActivities(sessionId, turnId);
        loadActivities(activityList);
        loadError.value = null;
        return;
      } catch (err) {
        lastErr = err;
        if (attempt < maxAttempts - 1) {
          const delay = baseDelay * 2 ** attempt;
          await new Promise((resolve) => setTimeout(resolve, delay));
        }
      }
    }

    const msg = lastErr instanceof Error ? lastErr.message : String(lastErr);
    loadError.value = msg;
    console.warn('[activity] failed to load activities from API after', maxAttempts, 'attempts:', msg);
  }

  /** Retry loading activities after a previous failure */
  async function retryLoad(sessionId: string, turnId?: string) {
    loadError.value = null;
    await loadActivitiesFromAPI(sessionId, turnId);
  }

  // === Cleanup on unmount (only when inside a component instance) ===

  if (getCurrentInstance()) {
    onUnmounted(() => {
      reset();
    });
  }

  return {
    activities: computed(() => Array.from(activities.value.values())),
    activityTree,
    streamEvents,
    rootActivityId,
    loadError: computed(() => loadError.value),
    handleActivityStart,
    handleActivityDelta,
    handleActivityDone,
    handleActivityChildStart,
    reset,
    loadActivities,
    loadActivitiesFromAPI,
    retryLoad,
  };
}

// === Mapping Functions ===

/**
 * Maps ActivityStatus to ToolActivity status.
 * Used by activityToStreamEvent for the action kind.
 */
export function mapActivityStatusToToolStatus(status: ActivityStatus): ToolActivity['status'] {
  switch (status) {
    case 'tool_running':
      return 'running';
    case 'tool_blocked':
      return 'blocked';
    case 'completed':
      return 'success';
    case 'failed':
    case 'partial_failure':
      return 'failed';
    case 'cancelled':
    case 'interrupted':
      return 'cancelled';
    default:
      return 'running';
  }
}

/**
 * Maps backend ActivityStatus to frontend PlanEvent.status.
 * Backend: pending → running → completed / partial_failure / failed
 * Frontend: planning → executing → completed / failed
 */
function mapPlanStatus(status: ActivityStatus): PlanEvent['status'] {
  switch (status) {
    case 'pending':
      return 'planning';
    case 'running':
      return 'executing';
    case 'completed':
      return 'completed';
    case 'partial_failure':
    case 'failed':
      return 'failed';
    default:
      return 'planning';
  }
}

/**
 * Maps an AF ActivityTreeNode to a StreamEvent (streamEventTypes).
 * This bridges the AF backend Activity model to the frontend rendering model.
 *
 * B-04: For plan nodes, the node's tree children are mapped to StreamEvent[]
 * and stored in PlanEvent.children, eliminating the need for PlanBlock to
 * directly consume activityTree.
 */
export function activityToStreamEvent(node: ActivityTreeNode): StreamEvent {
  switch (node.kind) {
    case 'thinking':
      return {
        kind: 'thinking',
        id: node.id,
        content: node.reasoning || node.content || '',
        label: node.label || undefined,
        collapsed: node.collapsed,
        streaming: node.status === 'running',
        durationMs: node.durationMs,
      } satisfies ThinkingEvent;

    case 'action': {
      const toolStatus = mapActivityStatusToToolStatus(node.status);
      const tool: ToolActivity = {
        toolName: node.toolName || '',
        toolLabel: node.label || node.toolName || '',
        status: toolStatus,
        durationMs: node.toolDurationMs ?? node.durationMs,
        arguments: node.toolArguments || null,
        result: node.toolResult || null,
        error: node.toolErrorCode || null,
      };
      return {
        kind: 'action',
        id: node.id,
        tool,
      } satisfies ActionEvent;
    }

    case 'reply':
      return {
        kind: 'reply',
        id: node.id,
        content: node.content || '',
        isFinal: node.status === 'completed' || node.status === 'failed',
        streaming: node.status === 'running',
        variant: 'default',
        durationMs: node.durationMs,
      } satisfies ReplyEvent;

    case 'error':
      return {
        kind: 'error',
        id: node.id,
        type: 'degradation',
        message: node.content || node.toolErrorCode || '',
        // P3-4: surface the error code so ErrorBlock can pick an inline
        // action. Prefer toolErrorCode (turn-level), then meta.error_code
        // (backend apierror.Code), so the most specific code wins.
        errorCode: node.toolErrorCode || (node.meta?.error_code as string | undefined) || undefined,
      } satisfies ErrorEvent;

    case 'plan': {
      // Map backend ActivityStatus → frontend PlanEvent.status
      const planStatus = mapPlanStatus(node.status);
      // Extract steps from meta (serialized from Go ActivityPlanStep[])
      const metaSteps = Array.isArray(node.meta?.steps) ? (node.meta.steps as PlanStep[]) : [];
      // B-04: Map tree children to StreamEvent[] for PlanBlock rendering.
      // This replaces the direct activityTree consumption in PlanBlock,
      // unifying the data flow through the event model.
      const childEvents: StreamEvent[] = (node.children ?? [])
        .filter((child) => child.kind !== 'task' && child.kind !== 'sub_task_board' && child.kind !== 'delegate')
        .map((child) => activityToStreamEvent(child));
      return {
        kind: 'plan',
        id: node.id,
        title: node.label || node.content || '',
        steps: metaSteps,
        status: planStatus,
        children: childEvents.length > 0 ? childEvents : undefined,
      } satisfies PlanEvent;
    }

    case 'notice': {
      const noticeType = (node.meta?.noticeType as NoticeEvent['type']) ?? 'info';
      return {
        kind: 'notice',
        id: node.id,
        type: noticeType,
        message: node.content || '',
      } satisfies NoticeEvent;
    }

    case 'confirm':
      return {
        kind: 'confirm',
        id: node.id,
        status: node.status as ConfirmEvent['status'],
        content: node.content || '',
        toolName: (node.meta?.toolName as string) || '',
        toolArguments: (node.meta?.toolArguments as string) ?? null,
        autoApproveAt: (node.meta?.autoApproveAt as string) ?? null,
      } satisfies ConfirmEvent;

    default:
      // Fallback: task, sub_task_board, delegate → error (degradation)
      return {
        kind: 'error',
        id: node.id,
        type: 'degradation',
        message: node.content || node.label || '',
      } satisfies ErrorEvent;
  }
}

import { nextTick, ref, type Ref, type ComputedRef } from 'vue';
import { useQuasar } from 'quasar';
import { useRouter } from 'vue-router';
import { useSessionStore } from '../../../stores/session';
import { useTeamsStore } from '../../../stores/teams';
import { usePlatformStore } from '../../../stores/platform';
import type { PlatformResourceTreeNode } from '../../platform/types';
import type { ChatEntityKind, TeamRow } from '../../../components/chat/types';
import type { Agent } from '../../agents/types';
import type { Session } from '../../session/types';
import { hydrateAgentSettings } from '../agentPlannerSettings';
import { hydrateSessionForChannelFocus } from '../channelFocusLoad';
import type { ChatFocusCoordinator, FocusSessionOptions } from '../chatFocusCoordinator';
export type { FocusSessionOptions } from '../chatFocusCoordinator';
import type { useAppStore } from '../../../stores/app';
import type { useChatSessionStore } from '../../../stores/chat/sessionStore';
import type { useChatMessageStore } from '../../../stores/chat/messageStore';
import type { Message } from '../types';
import type { useChatStreamManager } from './useChatStreamManager';

type AppStore = ReturnType<typeof useAppStore>;
type SessionStore = ReturnType<typeof useChatSessionStore>;
type MessageStore = ReturnType<typeof useChatMessageStore>;
type StreamManager = ReturnType<typeof useChatStreamManager>;

export type EntityNavDeps = {
  appStore: AppStore;
  sessionStore: SessionStore;
  messageStore: MessageStore;
  streamManager: StreamManager;
  focusCoordinator: ChatFocusCoordinator;
  displayAgents: Ref<Agent[]>;
  displayTeams: Ref<TeamRow[]>;
  dialogMode: Ref<string>;
  selectedProviderModel: Ref<{ provider?: string; model?: string } | undefined>;
  makeSessionTitle: (content: string) => string;
  t: (key: string, ...args: unknown[]) => string;
  /**
   * AF-FE-15: Load Activity records for the session and reconstruct per-round
   * `actv-*` messages. The channel-focus path (route watch, sidebar click,
   * session restore) routes through this so activity-driven UI is consistent
   * with the bindSessionView path.
   */
  loadActivitiesAndReconstruct: (sessionId: string) => Promise<Message[]>;
};

export function useChatEntityNav(deps: EntityNavDeps) {
  const $q = useQuasar();
  const router = useRouter();
  const taxonomyTree = ref<PlatformResourceTreeNode[]>([]);

  function sessionOwnerIsTeam(session: Session) {
    return session.owner_type === 'team' || Boolean(session.team_id?.trim());
  }

  async function resolveSessionById(sessionId: string): Promise<Session | null> {
    const hit = deps.sessionStore.findSessionById(sessionId);
    if (hit) return hit;
    try {
      const sessionStore = useSessionStore();
      return await sessionStore.fetchSession(sessionId);
    } catch {
      return null;
    }
  }

  async function loadTeamSessions(teamID: string) {
    await deps.sessionStore.loadTeamSessions(teamID);
  }

  async function loadTeams() {
    try {
      const teamsStore = useTeamsStore();
      await teamsStore.loadTeams();
      const rows = teamsStore.teams;
      deps.displayTeams.value = rows.map((team) => ({
        id: team.id,
        team_key: team.team_key,
        display_name: team.display_name,
        status: team.status,
        isDefault: team.is_default,
        isWorking: /work|run|busy|ing/i.test(team.status || ''),
        definition_json: team.definition_json,
      }));
    } catch {
      deps.displayTeams.value = [];
    }
  }

  async function loadTaxonomyTree() {
    const platformStore = usePlatformStore();
    await platformStore.loadTaxonomyTree();
    taxonomyTree.value = platformStore.taxonomyTree;
  }

  function channelFocusLoadDeps() {
    return {
      getMessages: (sid: string) => deps.messageStore.getMessages(sid),
      loadMessages: (opts: {
        sessionId: string;
        replace?: boolean;
        dropStaleInFlight?: boolean;
        activityMessages?: Message[];
      }) => deps.messageStore.loadMessages(opts),
      setMessages: (sid: string, rows: Message[]) => deps.messageStore.setMessages(sid, rows),
      ensureChatStream: (sid: string) => deps.streamManager.ensureChatStream(sid),
      loadActivitiesAndReconstruct: (sid: string) => deps.loadActivitiesAndReconstruct(sid),
    };
  }

  async function selectAgent(
    agent: Agent,
    options?: {
      sessionId?: string;
      skipMessageReload?: boolean;
      /** Deferred skip flag for merged concurrent channel focus (read immediately before hydrate). */
      resolveSkipMessageReload?: () => boolean;
    },
  ) {
    const sameAgent = deps.sessionStore.entityKind === 'agent' && deps.appStore.selectedAgent?.id === agent.id;

    if (deps.sessionStore.entityKind === 'team') {
      deps.streamManager.disconnectTeamStream();
      deps.messageStore.clearAllMessages();
    }
    if (!sameAgent) {
      deps.sessionStore.resetForAgentSwitch();
    }
    const resolved = await hydrateAgentSettings(agent);
    deps.appStore.selectedAgent = resolved;
    deps.appStore.upsertAgent(resolved);
    if (!sameAgent) {
      await deps.sessionStore.loadAgentSessions(resolved.id);
    } else {
      await deps.sessionStore.loadAgentSessions(resolved.id, { refreshOnly: true });
    }
    await nextTick();
    const preferredId = options?.sessionId?.trim();
    let picked =
      preferredId != null && preferredId !== ''
        ? (deps.sessionStore.sessions.find((item) => item.id === preferredId) ?? null)
        : (deps.sessionStore.sessions[0] ?? null);
    if (preferredId && !picked) {
      const fetched = await resolveSessionById(preferredId);
      if (fetched && fetched.agent_id?.trim() === resolved.id) {
        if (!deps.sessionStore.sessions.some((item) => item.id === preferredId)) {
          deps.sessionStore.sessions = [fetched, ...deps.sessionStore.sessions];
        }
        picked = fetched;
      }
    }
    deps.sessionStore.selectedSession = picked ?? deps.sessionStore.sessions[0] ?? null;
    if (deps.sessionStore.selectedSession) {
      const sid = deps.sessionStore.selectedSession.id;
      const skipReload = options?.resolveSkipMessageReload?.() ?? options?.skipMessageReload ?? false;
      // Sync URL so route watch and alreadyFocused checks stay consistent.
      const targetQuery: Record<string, string> = { session: sid, agent: resolved.id };
      const route = router.currentRoute.value;
      const routeSession = typeof route.query.session === 'string' ? route.query.session.trim() : '';
      const routeAgent = typeof route.query.agent === 'string' ? route.query.agent.trim() : '';
      if (route.name === 'chat' && (routeSession !== sid || routeAgent !== resolved.id)) {
        await deps.focusCoordinator.withRouteWatchSuppressed(async () => {
          await router.replace({ name: 'chat', query: targetQuery });
        });
      }
      await hydrateSessionForChannelFocus(channelFocusLoadDeps(), sid, skipReload);
    }
  }

  async function selectTeam(team: TeamRow, options?: { sessionId?: string }) {
    if (deps.sessionStore.selectedTeamId && deps.sessionStore.selectedTeamId !== team.id) {
      deps.streamManager.disconnectTeamStream();
      deps.messageStore.clearAllMessages();
    }
    deps.sessionStore.resetForTeamSwitch(team.id);
    await loadTeamSessions(team.id);
    const preferredId = options?.sessionId?.trim();
    const teamList = deps.sessionStore.teamSessions[team.id] ?? [];
    deps.sessionStore.teamSelectedSessionId = preferredId
      ? (teamList.find((item) => item.id === preferredId)?.id ?? preferredId)
      : (teamList[0]?.id ?? null);
    if (deps.sessionStore.teamSelectedSessionId) {
      await deps.messageStore.loadMessages({ sessionId: deps.sessionStore.teamSelectedSessionId, replace: true });
      deps.streamManager.ensureTeamStream(deps.sessionStore.teamSelectedSessionId);
    }
  }

  async function focusAgentSessionView(sessionId: string, agentId: string, options?: FocusSessionOptions) {
    const route = router.currentRoute.value;
    const routeSession = typeof route.query.session === 'string' ? route.query.session.trim() : '';
    const routeAgent = typeof route.query.agent === 'string' ? route.query.agent.trim() : '';
    const alreadyFocused =
      route.name === 'chat' &&
      routeSession === sessionId &&
      routeAgent === agentId &&
      deps.sessionStore.entityKind === 'agent' &&
      deps.appStore.selectedAgent?.id === agentId &&
      deps.sessionStore.selectedSession?.id === sessionId;

    if (alreadyFocused) {
      const session = deps.sessionStore.sessions.find((item) => item.id === sessionId);
      if (session) deps.sessionStore.selectedSession = session;
      await hydrateSessionForChannelFocus(channelFocusLoadDeps(), sessionId, options?.skipMessageReload);
      return;
    }

    const query = { session: sessionId, agent: agentId };
    const needsRouteSync = route.name !== 'chat' || routeSession !== sessionId || routeAgent !== agentId;
    await deps.focusCoordinator.withRouteWatchSuppressed(async () => {
      if (needsRouteSync) {
        if (route.name === 'chat') {
          await router.replace({ name: 'chat', query });
        } else {
          await router.push({ name: 'chat', query });
        }
      }
      // Route watch may not fire when query is unchanged; always focus in store.
      await focusSessionById(sessionId, agentId, options);
    });
  }

  async function onSelectSession(sessionId: string) {
    const resolved = await resolveSessionById(sessionId);
    if (!resolved) return;

    if (sessionOwnerIsTeam(resolved)) {
      const teamId = resolved.team_id?.trim();
      if (!teamId) return;
      const team = deps.displayTeams.value.find((item) => item.id === teamId);
      if (!team) {
        $q.notify({ type: 'warning', message: '找不到该会话所属的 Team' });
        return;
      }
      if (deps.sessionStore.entityKind !== 'team' || deps.sessionStore.selectedTeamId !== teamId) {
        await selectTeam(team, { sessionId });
        deps.streamManager.ensureTeamStream(sessionId);
        return;
      }
      deps.sessionStore.teamSelectedSessionId = sessionId;
      await deps.messageStore.loadMessages({ sessionId, replace: true });
      deps.streamManager.ensureTeamStream(sessionId);
      return;
    }

    const agentId =
      resolved.agent_id?.trim() ||
      (deps.sessionStore.sessions.some((item) => item.id === sessionId)
        ? deps.appStore.selectedAgent?.id?.trim()
        : '') ||
      '';
    if (!agentId) return;
    const agent =
      deps.appStore.agents.find((item) => item.id === agentId) ??
      deps.displayAgents.value.find((item) => item.id === agentId);
    if (!agent) {
      $q.notify({ type: 'warning', message: '找不到该会话所属的 Agent' });
      return;
    }
    await focusAgentSessionView(sessionId, agentId);
  }

  async function onRenameSession(payload: { id: string; title: string }) {
    const title = payload.title.trim();
    if (!title) return;
    try {
      await deps.sessionStore.renameSessionByKind(payload.id, title);
    } catch {
      $q.notify({ type: 'negative', message: '重命名失败，请重试' });
    }
  }

  async function onTogglePinSession(payload: { id: string; pinned: boolean }) {
    try {
      await deps.sessionStore.setSessionPinnedByKind(payload.id, payload.pinned);
    } catch {
      $q.notify({ type: 'negative', message: payload.pinned ? '置顶失败，请重试' : '取消置顶失败，请重试' });
    }
  }

  async function onRestoreSession(sessionId: string) {
    try {
      const sessionStore = useSessionStore();
      await sessionStore.restore(sessionId);
      if (deps.sessionStore.entityKind === 'team' && deps.sessionStore.selectedTeamId) {
        const teamId = deps.sessionStore.selectedTeamId;
        const sessions = deps.sessionStore.teamSessions[teamId] ?? [];
        deps.sessionStore.teamSessions[teamId] = sessions.map((s) =>
          s.id === sessionId ? { ...s, archived_at: '' } : s,
        );
      }
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '恢复会话失败' });
    }
  }

  async function onArchiveSession(sessionId: string) {
    try {
      const sessionStore = useSessionStore();
      await sessionStore.archive(sessionId);
      if (deps.sessionStore.entityKind === 'team' && deps.sessionStore.selectedTeamId) {
        const teamId = deps.sessionStore.selectedTeamId;
        const sessions = deps.sessionStore.teamSessions[teamId] ?? [];
        deps.sessionStore.teamSessions[teamId] = sessions.map((s) =>
          s.id === sessionId ? { ...s, archived_at: new Date().toISOString() } : s,
        );
      }
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '归档会话失败' });
    }
  }

  function onSessionDetail(sessionId: string) {
    router.push({ name: 'session-detail', params: { sessionId } });
  }

  async function onNewSession(title?: string) {
    if (deps.sessionStore.entityKind === 'agent' && deps.appStore.selectedAgent) {
      const selectedModel = deps.selectedProviderModel.value;
      await deps.sessionStore.addAgentSession(deps.appStore.selectedAgent.id, title || deps.t('chat.untitledSession'), {
        dialog_mode: deps.dialogMode.value,
        default_provider: selectedModel?.provider || deps.appStore.selectedAgent.provider,
        default_model: selectedModel?.model || deps.appStore.selectedAgent.model,
      });
      if (deps.sessionStore.selectedSession) {
        await deps.messageStore.loadMessages({ sessionId: deps.sessionStore.selectedSession.id });
        deps.streamManager.ensureChatStream(deps.sessionStore.selectedSession.id);
      }
      return;
    }

    if (deps.sessionStore.entityKind === 'team' && deps.sessionStore.selectedTeamId) {
      const selectedModel = deps.selectedProviderModel.value;
      const created = await deps.sessionStore.addTeamSession(
        deps.sessionStore.selectedTeamId,
        title || deps.t('chat.untitledSession'),
        {
          dialog_mode: deps.dialogMode.value,
          default_provider: selectedModel?.provider || '',
          default_model: selectedModel?.model || '',
        },
      );
      if (created) {
        deps.streamManager.ensureTeamStream(created.id);
      }
      return;
    }

    // No valid entity selected — notify the user instead of silently skipping
    $q.notify({
      type: 'warning',
      message: deps.t('chat.noEntityForNewSession', '请先选择一个 Agent 或团队以创建会话'),
    });
  }

  async function openSettings(kind: ChatEntityKind, id: string) {
    if (kind === 'agent') {
      await router.push(`/agents/${id}/settings`);
      return;
    }
    if (kind === 'team') {
      await router.push({ name: 'team', query: { edit: id } });
    }
  }

  async function focusSessionById(sessionId: string, agentId?: string, options?: FocusSessionOptions) {
    const sid = sessionId.trim();
    if (!sid) return;
    const key = deps.focusCoordinator.focusKey(sid, agentId);
    await deps.focusCoordinator.runFocusOnce(key, options, async (resolveSkipReload) => {
      const session = await resolveSessionById(sid);
      if (!session) {
        $q.notify({ type: 'warning', message: '找不到该会话' });
        return;
      }
      const aid = agentId?.trim() || session.agent_id?.trim() || deps.appStore.selectedAgent?.id?.trim();
      if (!aid) return;
      const agent =
        deps.appStore.agents.find((a) => a.id === aid) ?? deps.displayAgents.value?.find((a) => a.id === aid);
      if (!agent) {
        $q.notify({ type: 'warning', message: '找不到该会话所属的 Agent' });
        return;
      }
      await selectAgent(agent, { sessionId: sid, resolveSkipMessageReload: resolveSkipReload });
    });
  }

  return {
    taxonomyTree,
    loadTaxonomyTree,
    loadTeams,
    loadTeamSessions,
    selectAgent,
    selectTeam,
    focusAgentSessionView,
    focusSessionById,
    onSelectSession,
    onRenameSession,
    onTogglePinSession,
    onRestoreSession,
    onArchiveSession,
    onSessionDetail,
    onNewSession,
    openSettings,
    updateTeam: async (id: string, payload: object) => {
      const teamsStore = useTeamsStore();
      return teamsStore.editTeam(id, payload) as unknown as Promise<import('../../../components/chat/types').TeamRow>;
    },
  };
}

import { ref, type Ref } from 'vue';
import { useChatRuntimeStore } from '../../../stores/chat/runtimeStore';
import type { RunStatus, RunStatusValue } from '../types';
import type { Envelope } from '../envelope';
import { runStatusFromEnvelope, messageQueuedFromEnvelope } from '../envelopeRunStatus';

const HYDRATE_DELAY_MS = 400;

type UseChatRunStatusDeps = {
  applyAwaitRunStatus: (rs: RunStatus) => void;
};

/**
 * WS-primary run status: envelopes update state immediately; HTTP hydrates only
 * when WS has not yet reported for the current session (e.g. after session switch).
 */
export function useChatRunStatus(deps: UseChatRunStatusDeps) {
  const runStatus: Ref<RunStatusValue> = ref('idle');
  const runMeta: Ref<RunStatus | null> = ref(null);

  let wsAuthoritative = false;
  let hydrateTimer: ReturnType<typeof setTimeout> | null = null;
  let hydrateSessionId = '';
  /** Whether we are currently hydrating after a session switch (suppresses stale flash). */
  let hydrating = false;

  function clearHydrateTimer() {
    if (hydrateTimer) {
      clearTimeout(hydrateTimer);
      hydrateTimer = null;
    }
  }

  function resetRunStatus() {
    clearHydrateTimer();
    wsAuthoritative = false;
    hydrating = false;
    hydrateSessionId = '';
    runStatus.value = 'idle';
    runMeta.value = null;
  }

  function applyFromEnvelope(env: Envelope) {
    if (messageQueuedFromEnvelope(env)) return;
    const rs = runStatusFromEnvelope(env);
    if (!rs) return;
    wsAuthoritative = true;
    clearHydrateTimer();
    runStatus.value = rs.status;
    const meta: RunStatus = {
      status: rs.status,
      runId: rs.runId,
      errorMessage: rs.errorMessage,
      awaitKind: rs.awaitKind,
      awaitToolKey: rs.awaitToolKey,
      awaitToolCallId: rs.awaitToolCallId,
      updatedAt: '',
    };
    runMeta.value = meta;
    deps.applyAwaitRunStatus(meta);
  }

  function scheduleHttpHydrate(sessionId: string) {
    hydrateSessionId = sessionId;
    wsAuthoritative = false;
    hydrating = true;
    clearHydrateTimer();
    hydrateTimer = setTimeout(() => {
      void hydrateFromHttpIfNeeded(sessionId);
    }, HYDRATE_DELAY_MS);
  }

  async function hydrateFromHttpIfNeeded(sessionId: string) {
    if (!sessionId || sessionId !== hydrateSessionId || wsAuthoritative) return;
    try {
      const runtime = useChatRuntimeStore();
      const rs = await runtime.fetchRunStatus(sessionId);
      if (sessionId !== hydrateSessionId || wsAuthoritative) return;
      runStatus.value = rs.status;
      runMeta.value = rs;
      deps.applyAwaitRunStatus(rs);
    } catch {
      /* ignore transient hydrate failures */
    } finally {
      hydrating = false;
    }
  }

  /** Fallback HTTP refresh; skipped when WS already authoritative for this session. */
  async function refreshRunStatus(sessionId?: string) {
    if (!sessionId) {
      resetRunStatus();
      return;
    }
    await hydrateFromHttpIfNeeded(sessionId);
  }

  function onSessionSwitch(sessionId: string | undefined) {
    if (!sessionId) {
      resetRunStatus();
      return;
    }
    // Don't reset to "idle" immediately — keep previous value until HTTP hydrate
    // completes to avoid a brief incorrect "idle" flash during session switch.
    // The hydrate will set the correct status within HYDRATE_DELAY_MS.
    scheduleHttpHydrate(sessionId);
  }

  /** Force-set run status (used when backend rejects enqueue due to stale state). */
  function forceSetRunStatus(status: RunStatusValue) {
    wsAuthoritative = true;
    clearHydrateTimer();
    runStatus.value = status;
    if (status === 'idle') {
      runMeta.value = null;
    }
  }

  return {
    runStatus,
    runMeta,
    applyFromEnvelope,
    onSessionSwitch,
    refreshRunStatus,
    forceSetRunStatus,
  };
}

import { ref, reactive, computed, type Ref, type ComputedRef } from 'vue';
import { useQuasar } from 'quasar';
import { useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { useChatRuntimeStore } from '../../../stores/chat/runtimeStore';
import { useChatSessionStore } from '../../../stores/chat/sessionStore';
import { useChatMessageStore } from '../../../stores/chat/messageStore';
import { useAuthStore } from '../../../stores/auth';
import { useAppStore } from '../../../stores/app';
import { checkBackendHealth, getServerHeartbeatState } from '../../heartbeat/useServerHeartbeat';
import type { ChatAttachment, ChatEntityKind } from '../../../components/chat/types';
import type { UseEnvelopeStreamReturn } from '../useEnvelopeStream';
import type { WsUpstream } from '../envelope';
import { createPlaceholderMessage } from '../streamHandlers';
import { shouldBlockAttachmentsForModel } from '../modelCapabilities';
// TECH-DEBT resolved: moved sendMessage to runtimeStore.send — chat optimization
import { AWAIT_KIND_TOOL_CONFIRM } from '../awaitConstants';
import { sendCommand } from '../../../realtime/command_channel';
import {
  CHAT_RUN_STALL_CHECK_INTERVAL_MS,
  CHAT_RUN_STALL_NOTIFY_THRESHOLD_MS,
  CHAT_STALL_NOTIFY_DURATION_MS,
  CHAT_FIRST_BYTE_NOTIFY_THRESHOLD_MS,
  CHAT_FIRST_BYTE_NOTIFY_DURATION_MS,
} from '../../constants/timeouts';

import type { RunStatusValue } from '../types';

type SessionStore = ReturnType<typeof useChatSessionStore>;
type MessageStore = ReturnType<typeof useChatMessageStore>;

type SendStrategy = {
  resolveSessionId: () => string | undefined;
  ensureSession: (title: string) => Promise<void>;
  resolveProviderModel: () => { provider: string; model: string };
  buildWsPayload: (
    sessionId: string,
    pendingUserId: string,
    content: string,
    provider: string,
    model: string,
  ) => WsUpstream;
  ensureStream: (sessionId: string) => UseEnvelopeStreamReturn;
  httpFallbackKeys: { agentKey: string | undefined; teamId: string | undefined };
  errorLabel: string;
};

export type SenderDeps = {
  appStore: ReturnType<typeof useAppStore>;
  sessionStore: SessionStore;
  messageStore: MessageStore;
  inputText: Ref<string>;
  dialogMode: Ref<string>;
  attachments: Ref<ChatAttachment[]>;
  isAwaitingUser: Ref<boolean>;
  awaitingRunId: Ref<string>;
  awaitKind: Ref<string>;
  runStatus: Ref<string>;
  selectedProviderModel: ComputedRef<
    | {
        provider: string;
        model: string;
        capabilities?: { vision?: boolean; image?: boolean; text_only?: boolean };
      }
    | undefined
  >;
  selectedKnowledgeBases: Ref<string[]>;
  ensureChatStream: (sessionId: string) => UseEnvelopeStreamReturn;
  ensureTeamStream: (sessionId: string) => UseEnvelopeStreamReturn;
  sendChatViaWs: (stream: UseEnvelopeStreamReturn, upstream: WsUpstream) => void;
  onNewSession: (title?: string) => Promise<void>;
  makeSessionTitle: (content: string) => string;
  refreshRunStatus: () => Promise<void>;
  setRunStatus: (status: RunStatusValue) => void;
  submitAwaitingReply: () => Promise<void>;
  submitToolConfirm: (approved: boolean) => Promise<void>;
  refreshPendingMessages?: () => Promise<void>;
};

export function useChatSender(deps: SenderDeps) {
  const $q = useQuasar();
  const router = useRouter();
  const { t } = useI18n();
  const runtime = useChatRuntimeStore();

  const sending = ref(false);

  // T1.5: No-Timeout principle — removed sendingTimeout, turnAckTimeout.
  // Tasks run until completion or user cancel. The stall check and first-byte
  // notice are notification-only; they never mark messages as failed.

  let firstByteNoticeTimeout: ReturnType<typeof setTimeout> | null = null;
  let stallNotified = false;

  let lastRunEventAt = 0;
  let stallCheckInterval: ReturnType<typeof setInterval> | null = null;

  const failedPendingIds = reactive(new Map<string, string>());

  function clearStallCheck() {
    if (stallCheckInterval != null) {
      clearInterval(stallCheckInterval);
      stallCheckInterval = null;
    }
  }

  function startStallCheck() {
    clearStallCheck();
    stallNotified = false;
    stallCheckInterval = setInterval(() => {
      if (!sending.value || lastRunEventAt === 0) return;
      // T1.5: notification-only — show a "please wait" notice after the
      // threshold, but never mark the message as failed or interrupt the run.
      if (!stallNotified && Date.now() - lastRunEventAt > CHAT_RUN_STALL_NOTIFY_THRESHOLD_MS) {
        stallNotified = true;
        $q.notify({
          type: 'info',
          message: t('chat.runStallWarning', '响应时间较长，模型仍在处理中，请耐心等待'),
          timeout: CHAT_STALL_NOTIFY_DURATION_MS,
        });
      }
    }, CHAT_RUN_STALL_CHECK_INTERVAL_MS);
  }

  function markSending(sessionId?: string) {
    sending.value = true;
    startStallCheck();
  }

  function markSendingDone() {
    sending.value = false;
    clearFirstByteNotice();
    clearStallCheck();
  }

  function clearFirstByteNotice() {
    if (firstByteNoticeTimeout != null) {
      clearTimeout(firstByteNoticeTimeout);
      firstByteNoticeTimeout = null;
    }
  }

  // T1.5: clearSendingTimeout is now a no-op — the sending timeout was removed.
  // Kept for backward compatibility with streamHandlers and useChatWorkspace.
  function clearSendingTimeout() {
    // no-op: No-Timeout principle
  }

  // T1.5: turnAckTimeout removed — no client-side turn-ack timeout.
  // The backend will process the message; if it fails, an error event arrives.

  function onFirstByteArrived() {
    clearFirstByteNotice();
  }

  function onRunAccepted() {
    clearFirstByteNotice();
    // T1.5: notification-only — show a "model thinking" notice after the
    // threshold, but never mark the message as failed.
    firstByteNoticeTimeout = setTimeout(() => {
      if (sending.value) {
        $q.notify({
          type: 'info',
          message: t('chat.firstByteTimeout', '模型正在思考中，请耐心等待'),
          timeout: CHAT_FIRST_BYTE_NOTIFY_DURATION_MS,
        });
        clearFirstByteNotice();
      }
    }, CHAT_FIRST_BYTE_NOTIFY_THRESHOLD_MS);
  }

  function touchRunActivity() {
    lastRunEventAt = Date.now();
  }

  function clearFailedPendingForSession(sessionId?: string) {
    if (!sessionId) {
      failedPendingIds.clear();
      return;
    }
    for (const [pendingId, sid] of failedPendingIds) {
      if (sid === sessionId) failedPendingIds.delete(pendingId);
    }
  }

  function stopStreaming(sessionId?: string) {
    if (sessionId) {
      runtime.stop(sessionId);
    }
    markSendingDone();
  }

  async function submitAwaitingReply() {
    await deps.submitAwaitingReply();
  }

  async function checkBackendAvailability(): Promise<boolean> {
    const heartbeat = getServerHeartbeatState();
    let backendUp = heartbeat.isAlive.value;
    if (!backendUp) {
      backendUp = await checkBackendHealth();
      if (backendUp) {
        heartbeat.isAlive.value = true;
      }
    }
    if (!backendUp) {
      const msg = import.meta.env.DEV
        ? t(
            'chat.backendUnavailableDev',
            '后端不可用，请确认 admin 是否在 :8000 运行（页面应使用 http://localhost:9001）',
          )
        : t('chat.backendUnavailable', '后端服务不可用，请重新登录');
      $q.notify({ type: 'negative', message: msg, timeout: import.meta.env.DEV ? 8000 : 0 });
      if (!import.meta.env.DEV) {
        const auth = useAuthStore();
        auth.user = null;
        auth.sessionChecked = true;
        router.push({ name: 'login' });
      }
      return false;
    }
    return true;
  }

  function isActiveRun(): boolean {
    const s = deps.runStatus.value;
    return s === 'running' || s === 'pending';
  }

  const inputDisabled = computed(() => {
    if (isActiveRun()) return false;
    return sending.value;
  });

  async function onSend() {
    const content = deps.inputText.value.trim();
    if (!content) {
      return;
    }
    if (!isActiveRun() && sending.value) {
      return;
    }

    if (deps.isAwaitingUser.value) {
      if (deps.awaitKind.value === AWAIT_KIND_TOOL_CONFIRM) {
        $q.notify({ type: 'info', message: t('chat.toolConfirmUseButtons', '请使用批准或拒绝按钮来确认工具调用') });
        return;
      }
      await submitAwaitingReply();
      return;
    }

    if (deps.sessionStore.entityKind === 'agent') {
      await sendAgentMessage(content);
    } else if (deps.sessionStore.entityKind === 'team' && deps.sessionStore.selectedTeamId) {
      await sendTeamMessage(content);
    } else {
      const reason = !deps.sessionStore.entityKind
        ? t('chat.noEntitySelected', '请先选择一个 Agent 或团队')
        : deps.sessionStore.entityKind === 'team'
          ? t('chat.noTeamSelected', '请先选择一个团队')
          : t('chat.unsupportedEntity', '不支持的实体类型');
      $q.notify({ type: 'warning', message: reason });
    }
  }

  function dropPendingUserRow(sessionId: string, pendingUserId: string) {
    failedPendingIds.delete(pendingUserId);
    deps.messageStore.setMessages(
      sessionId,
      deps.messageStore.getMessages(sessionId).filter((m) => m.id !== pendingUserId),
    );
  }

  function markPendingUserFailed(sessionId: string, pendingUserId: string, errorMsg: string) {
    failedPendingIds.set(pendingUserId, sessionId);
    const msgs = deps.messageStore.getMessages(sessionId);
    deps.messageStore.setMessages(
      sessionId,
      msgs.map((m) => (m.id === pendingUserId ? { ...m, status: 'failed', error_message: errorMsg } : m)),
    );
  }

  async function retryFailedMessage(pendingUserId: string) {
    const sid = deps.sessionStore.selectedSession?.id ?? deps.sessionStore.teamSelectedSessionId;
    if (!sid) return;
    const msgs = deps.messageStore.getMessages(sid);
    const failed = msgs.find((m) => m.id === pendingUserId);
    if (!failed || failed.status !== 'failed') return;

    // 问题 4 修复：活跃 run 期间重试失败消息时，直接入队而非走 sendUserContent。
    // sendUserContent 在 followUp=true 时会进入 enqueueDuringRun 路径并 dropPendingUserRow，
    // 但此前已将状态重置为 'ok'，用户既看不到失败标记也看不到排队反馈。
    // 正确做法：检测到活跃 run 时直接 enqueue，成功后移除失败行并提示已加入队列，
    // 消息通过 ChatPendingQueue 展示，提供清晰的重试反馈。
    if (isActiveRun()) {
      const runtime = useChatRuntimeStore();
      try {
        const res = await runtime.enqueue(sid, failed.content_markdown);
        if (res.accepted) {
          dropPendingUserRow(sid, pendingUserId);
          $q.notify({
            type: 'info',
            message: t('chat.retryQueuedDuringRun', '当前有任务执行中，已加入队列'),
          });
          await deps.refreshPendingMessages?.();
          return;
        }
        $q.notify({
          type: 'warning',
          message: t('chat.retryEnqueueRejected', '重试失败，请稍后再试'),
        });
      } catch (err: unknown) {
        const errMessage = err instanceof Error ? err.message : '';
        if (errMessage.includes('CHAT_QUEUE_FULL')) {
          $q.notify({ type: 'warning', message: t('chat.enqueueQueueFull', '排队消息已满，请稍后再试') });
        } else {
          $q.notify({
            type: 'negative',
            message: err instanceof Error ? err.message : t('chat.retryEnqueueRejected', '重试失败，请稍后再试'),
          });
        }
      }
      return;
    }

    // 无活跃 run：重置状态并重新发送（复用 pendingId 避免占位闪烁）
    failedPendingIds.delete(pendingUserId);
    deps.messageStore.setMessages(
      sid,
      msgs.map((m) => (m.id === pendingUserId ? { ...m, status: 'ok', error_message: '' } : m)),
    );
    const entityKind = deps.sessionStore.entityKind;
    if (entityKind === 'team') {
      await sendTeamMessage(failed.content_markdown, pendingUserId);
    } else {
      await sendAgentUserContent(failed.content_markdown, pendingUserId);
    }
  }

  async function enqueueDuringRun(sessionId: string, content: string, pendingUserId: string) {
    const runtime = useChatRuntimeStore();
    try {
      const res = await runtime.enqueue(sessionId, content);
      if (res.accepted) {
        dropPendingUserRow(sessionId, pendingUserId);
        // T5.3: Clear input only after successful enqueue (matches Path B
        // onEnqueueWhileRunning behavior). For follow-up sends, input was
        // intentionally not cleared in sendUserContent so the user can retry
        // if enqueue fails.
        deps.inputText.value = '';
        $q.notify({
          type: 'positive',
          message: res.queued
            ? t('chat.enqueueQueued', 'Message queued for after the current run')
            : t('chat.enqueueAccepted', 'Message will be injected at the next tool boundary'),
        });
        await deps.refreshPendingMessages?.();
        return;
      }
      dropPendingUserRow(sessionId, pendingUserId);
      deps.setRunStatus('idle');
      await sendUserContent(deps.sessionStore.entityKind, content);
    } catch (err: unknown) {
      dropPendingUserRow(sessionId, pendingUserId);
      const errMessage = err instanceof Error ? err.message : '';
      if (errMessage.includes('CHAT_RUN_ENDED')) {
        deps.setRunStatus('idle');
        await sendUserContent(deps.sessionStore.entityKind, content);
      } else if (errMessage.includes('CHAT_QUEUE_FULL')) {
        $q.notify({ type: 'warning', message: t('chat.enqueueQueueFull', '排队消息已满，请稍后再试') });
      } else {
        $q.notify({
          type: 'negative',
          message: err instanceof Error ? err.message : t('chat.enqueueRejected', 'Could not enqueue message'),
        });
      }
    }
  }

  async function sendViaHttpFallback(
    sessionId: string,
    content: string,
    agentKey: string | undefined,
    teamId: string | undefined,
    options: {
      dialogMode: string;
      provider: string;
      model: string;
      attachments: ChatAttachment[];
      knowledgeBases: string[];
    },
  ): Promise<void> {
    // B2: HTTP command channel — submit message and get ACK only.
    // Full message/state data arrives via the WS data channel.
    // Do NOT call loadMessages after HTTP success — the WS data channel
    // is the single source of truth for message data.
    await sendCommand({
      session_id: sessionId,
      agent_key: agentKey,
      team_id: teamId,
      content,
      options: {
        dialog_mode: options.dialogMode,
        provider: options.provider,
        model: options.model,
        attachments: options.attachments.map((a) => ({ id: a.id })),
        knowledge_bases: options.knowledgeBases,
      },
    });
  }

  function notifyUnsupportedImageModel() {
    $q.notify({
      type: 'warning',
      message: t('chat.imageModelUnsupported', '当前模型不支持图片理解，请移除图片附件或切换到支持视觉的模型'),
    });
  }

  function getAgentStrategy(): SendStrategy {
    return {
      resolveSessionId: () => deps.sessionStore.selectedSession?.id,
      ensureSession: async (title) => {
        if (!deps.sessionStore.selectedSession) await deps.onNewSession(title);
      },
      resolveProviderModel: () => {
        const selectedModel = deps.selectedProviderModel.value;
        const provider =
          selectedModel?.provider ||
          deps.sessionStore.selectedSession?.provider ||
          deps.appStore.selectedAgent?.provider ||
          '';
        const model =
          selectedModel?.model || deps.sessionStore.selectedSession?.model || deps.appStore.selectedAgent?.model || '';
        return { provider, model };
      },
      buildWsPayload: (sessionId, pendingUserId, content, provider, model) => ({
        direction: 'client_to_server',
        channel: 'chat',
        type: 'user_message',
        request_id: pendingUserId,
        payload: {
          session_id: sessionId,
          agent_key: deps.appStore.selectedAgent?.agent_key,
          content,
          options: {
            dialog_mode: deps.dialogMode.value,
            provider,
            model,
            attachments: deps.attachments.value.map((item) => ({ id: item.id })),
            knowledge_bases: deps.selectedKnowledgeBases.value,
          },
        },
      }),
      ensureStream: deps.ensureChatStream,
      httpFallbackKeys: { agentKey: deps.appStore.selectedAgent?.agent_key, teamId: undefined },
      errorLabel: t('chat.sendFailed', '发送失败，请稍后重试'),
    };
  }

  function getTeamStrategy(): SendStrategy {
    return {
      resolveSessionId: () => deps.sessionStore.teamSelectedSessionId ?? undefined,
      ensureSession: async (title) => {
        if (!deps.sessionStore.teamSelectedSessionId) await deps.onNewSession(title);
      },
      resolveProviderModel: () => {
        const selectedModel = deps.selectedProviderModel.value;
        const teamId = deps.sessionStore.selectedTeamId!;
        const session = deps.sessionStore.teamSessions[teamId]?.find(
          (item) => item.id === deps.sessionStore.teamSelectedSessionId,
        );
        const provider = selectedModel?.provider || session?.provider || '';
        const model = selectedModel?.model || session?.model || '';
        return { provider, model };
      },
      buildWsPayload: (sessionId, pendingUserId, content, provider, model) => ({
        direction: 'client_to_server',
        channel: 'chat',
        type: 'user_message',
        request_id: pendingUserId,
        payload: {
          session_id: sessionId,
          team_id: deps.sessionStore.selectedTeamId,
          content,
          options: {
            dialog_mode: deps.dialogMode.value,
            provider,
            model,
            attachments: deps.attachments.value.map((item) => ({ id: item.id })),
            knowledge_bases: deps.selectedKnowledgeBases.value,
          },
        },
      }),
      ensureStream: deps.ensureTeamStream,
      httpFallbackKeys: { agentKey: undefined, teamId: deps.sessionStore.selectedTeamId ?? undefined },
      errorLabel: t('chat.teamSendFailed', 'Team 发送失败'),
    };
  }

  async function sendUserContent(entityKind: ChatEntityKind, content: string, reusePendingId?: string) {
    const strategy = entityKind === 'team' ? getTeamStrategy() : getAgentStrategy();
    const text = content.trim();
    if (!text) return;
    const followUp = isActiveRun();
    // S-03: Do not call markSending() before session is resolved — it starts
    // the stall check and dispatch timeout prematurely. The second call below
    // (after ensureSession) is the correct one.
    let clearAttachments = false;
    try {
      await strategy.ensureSession(deps.makeSessionTitle(text));
      const sessionId = strategy.resolveSessionId();
      if (!sessionId) {
        $q.notify({ type: 'negative', message: t('chat.sessionCreateFailed', '未创建会话或会话无效，请重试') });
        if (!followUp) markSendingDone();
        return;
      }
      if (!followUp) {
        markSending(sessionId);
      }

      const pendingUserId = reusePendingId ?? `pending-user-${crypto.randomUUID()}`;
      if (!reusePendingId) {
        // T5.3: For follow-up (enqueue during active run), don't create a
        // pending-user placeholder and don't clear input yet. The queued
        // message will appear in ChatPendingQueue via refreshPendingMessages,
        // providing consistent UX with the onEnqueueWhileRunning path (Path B).
        // Input is cleared only after enqueue succeeds (inside enqueueDuringRun),
        // so the user can retry if enqueue fails (e.g., backend unavailable,
        // queue full). The dropPendingUserRow calls in enqueueDuringRun become
        // no-ops (safe — filter on non-existent id returns unchanged list).
        if (!followUp) {
          deps.inputText.value = '';
          deps.messageStore.setMessages(sessionId, [
            ...deps.messageStore.getMessages(sessionId),
            createPlaceholderMessage(pendingUserId, sessionId, 'user', text),
          ]);
        }
      }

      const { provider, model } = strategy.resolveProviderModel();
      const selectedModel = deps.selectedProviderModel.value;
      const blockReason = shouldBlockAttachmentsForModel(
        { provider, model, capabilities: selectedModel?.capabilities },
        deps.attachments.value,
      );
      if (blockReason) {
        if (blockReason === 'ATTACHMENT_UNSUPPORTED') {
          $q.notify({
            type: 'warning',
            message: t('chat.fileModelUnsupported', '当前模型不支持文件附件，请移除附件或切换模型'),
          });
        } else {
          notifyUnsupportedImageModel();
        }
        if (!reusePendingId) dropPendingUserRow(sessionId, pendingUserId);
        if (!followUp) markSendingDone();
        return;
      }

      if (!(await checkBackendAvailability())) {
        markPendingUserFailed(sessionId, pendingUserId, t('chat.sendFailedBackend', '后端不可用'));
        if (!followUp) markSendingDone();
        return;
      }

      if (followUp) {
        await enqueueDuringRun(sessionId, text, pendingUserId);
        return;
      }

      try {
        const stream = strategy.ensureStream(sessionId);
        deps.sendChatViaWs(stream, strategy.buildWsPayload(sessionId, pendingUserId, text, provider, model));
        // T1.5: No turn-ack timeout — the backend processes the message and
        // sends run.status=running as an early ack. If it fails, an error
        // event arrives. No client-side timeout marks the message as failed.
        // Clear attachments only after WS send is dispatched successfully.
        // If the backend fails, the error envelope will arrive later and
        // the user can retry with the same attachments still attached.
        clearAttachments = true;
      } catch (wsError) {
        $q.notify({ type: 'info', message: t('chat.wsFallbackHttp', 'WebSocket 不可用，正在通过 HTTP 发送…') });
        try {
          await sendViaHttpFallback(
            sessionId,
            text,
            strategy.httpFallbackKeys.agentKey,
            strategy.httpFallbackKeys.teamId,
            {
              dialogMode: deps.dialogMode.value,
              provider,
              model,
              attachments: deps.attachments.value,
              knowledgeBases: deps.selectedKnowledgeBases.value,
            },
          );
          // B2: HTTP command channel returns ACK only — no loadMessages.
          // The WS data channel pushes the persisted message and subsequent
          // streaming/state events. markSendingDone so the sending state
          // doesn't stay true; the WS data channel will deliver the message.
          if (!followUp) markSendingDone();
          clearAttachments = true;
          // B2: Drop the pending user row — the WS data channel will deliver
          // the server-persisted user message. If the WS is disconnected,
          // the next reconnect sync (event_replay) will fetch missed messages.
          dropPendingUserRow(sessionId, pendingUserId);
        } catch (httpError) {
          markPendingUserFailed(sessionId, pendingUserId, t('chat.sendFailedRetry', '发送失败，请点击重试'));
          if (!followUp) markSendingDone();
        }
      }
    } catch (error) {
      if (!(error instanceof DOMException && error.name === 'AbortError')) {
        const sid = strategy.resolveSessionId();
        if (sid) {
          const pendingId = deps.messageStore
            .getMessages(sid)
            .find((m) => m.content_markdown === text && m.id.startsWith('pending-user-'))?.id;
          if (pendingId) {
            markPendingUserFailed(sid, pendingId, t('chat.sendFailedRetry', '发送失败，请点击重试'));
          }
        }
        $q.notify({
          type: 'negative',
          message: error instanceof Error ? error.message : strategy.errorLabel,
        });
        if (!followUp) markSendingDone();
      }
    } finally {
      if (clearAttachments) {
        deps.attachments.value = [];
      }
    }
  }

  async function sendAgentUserContent(content: string, reusePendingId?: string) {
    await sendUserContent('agent', content, reusePendingId);
  }

  async function sendAgentMessage(content: string) {
    await sendAgentUserContent(content);
  }

  async function sendTeamMessage(content: string, reusePendingId?: string) {
    await sendUserContent('team', content, reusePendingId);
  }

  return {
    sending,
    inputDisabled,
    markSending,
    markSendingDone,
    clearSendingTimeout,
    onRunAccepted,
    onFirstByteArrived,
    stopStreaming,
    submitAwaitingReply,
    submitToolConfirm: deps.submitToolConfirm,
    onSend,
    sendAgentUserContent,
    sendTeamMessage,
    retryFailedMessage,
    touchRunActivity,
    clearFailedPendingForSession,
    failedPendingIds,
  };
}

import { ref, type Ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { useQuasar } from 'quasar';
import { useRouter } from 'vue-router';
import { useChatStreamingSnapshots } from '../../../stores/chatStreamingSnapshots';
import { useAuthStore } from '../../../stores/auth';
import { useChatSessionStore } from '../../../stores/chat/sessionStore';
import { useChatMessageStore } from '../../../stores/chat/messageStore';
import { useChatRuntimeStore } from '../../../stores/chat/runtimeStore';
import { createChatStream, createTeamStream, type UseEnvelopeStreamReturn } from '../useEnvelopeStream';
import type { Envelope, EnvelopeType, WsUpstream } from '../envelope';
import { bindStreamHandlers, patchStreamingEnvelope } from '../streamHandlers';
import { getChannelWsCursor } from '../channelWsCursor';
import { reloadSessionAfterCompletion } from '../sessionCompletionReload';
import type { TeamRow } from '../../../components/chat/types';
import type { TeamDefinition } from '../../teams/types';

export type StreamManagerDeps = {
  sessionStore: ReturnType<typeof useChatSessionStore>;
  messageStore: ReturnType<typeof useChatMessageStore>;
  runtimeStore: ReturnType<typeof useChatRuntimeStore>;
  displayTeams: Ref<TeamRow[]>;
  resolveAgentId: () => string | undefined;
  markSendingDone: () => void;
  clearSendingTimeout: () => void;
  onRunAccepted: () => void;
  onRunStatus: (env: Envelope) => void;
  touchRunActivity: () => void;
  onFirstByteArrived: () => void;
  refreshRunStatus: (sessionId?: string) => Promise<void>;
  onCompressNotice?: (sessionId: string, prevRatio: number, newRatio: number) => void;
  // T1.6: Real-time AF integration. Route activity envelopes from the stream
  // directly to useActivityTimeline so the UI updates in real-time without
  // waiting for the inbound-sync polling path.
  onActivityEnvelope?: (env: Envelope) => void;
};

export function useChatStreamManager(deps: StreamManagerDeps) {
  const { t } = useI18n();
  const $q = useQuasar();
  const router = useRouter();
  const streamingSnapshots = useChatStreamingSnapshots();

  let chatStream: UseEnvelopeStreamReturn | null = null;
  let chatStreamSessionId: string | null = null;
  let chatStreamCleanup: (() => void) | null = null;
  let teamStream: UseEnvelopeStreamReturn | null = null;
  let teamStreamSessionId: string | null = null;
  let teamStreamCleanup: (() => void) | null = null;

  const wsReplaying = ref(false);
  let lastErrorNotifyMessage = '';
  let lastErrorNotifyAt = 0;

  /**
   * Ordered execution_progress envelopes for the active chat / team stream.
   * Implemented as a bounded ring buffer (S2 + S11):
   *   - O(1) `pushProgress` append (the spread pattern was O(n) per insert)
   *   - capped at MAX_PROGRESS_ENVELOPES to keep long sessions bounded
   *   - cleared on stream re-create and on every new run-accepted
   *
   * The exposed ref shares the underlying array — Vue 3's reactive array
   * tracking handles `push()` / `splice()` correctly, so we don't need to
   * clone the buffer on every mutation. The TS type is `readonly Envelope[]`
   * so consumers cannot accidentally mutate it.
   *
   * @see docs/reports/2026-06-10-proposal-execution-progress-inline.md
   */
  const MAX_PROGRESS_ENVELOPES = 200;
  const progressBuffer: Envelope[] = [];
  const executionProgress = ref<readonly Envelope[]>(progressBuffer);

  function pushProgress(env: Envelope): void {
    progressBuffer.push(env);
    if (progressBuffer.length > MAX_PROGRESS_ENVELOPES) {
      // Drop oldest envelopes to keep the buffer bounded. Amortized O(1)
      // per push — `splice(0, n)` only runs when we overflow.
      const overflow = progressBuffer.length - MAX_PROGRESS_ENVELOPES;
      progressBuffer.splice(0, overflow);
    }
    // Vue 3's reactive ref tracks array mutations on `.push()`/`.splice()`
    // automatically. We do NOT re-assign `.value` to avoid the spread cost.
  }

  function clearProgress(): void {
    progressBuffer.length = 0;
  }

  function notifyError(message: string) {
    const now = Date.now();
    if (message === lastErrorNotifyMessage && now - lastErrorNotifyAt < 5000) {
      return;
    }
    lastErrorNotifyMessage = message;
    lastErrorNotifyAt = now;
    $q.notify({ type: 'negative', message, group: 'chat-stream-error' });
  }

  function notifyOrchestration(message: string) {
    $q.notify({ type: 'info', message, timeout: 4000, group: false });
  }

  async function reloadSessionMessagesAfterCompletion(sessionId: string) {
    try {
      await reloadSessionAfterCompletion({
        sessionStore: deps.sessionStore,
        messageStore: deps.messageStore,
        streamingSnapshots,
        sessionId,
        resolveAgentId: deps.resolveAgentId,
      });
    } catch (err) {
      notifyError(err instanceof Error ? err.message : t('chat.loadMessagesFailed', '加载消息失败'));
    }
  }

  function resolveTeamMemberMeta(agentKey: string) {
    const team = deps.displayTeams.value.find((row) => row.id === deps.sessionStore.selectedTeamId);
    const def: TeamDefinition | null = (() => {
      try {
        return team?.definition_json ? (JSON.parse(team.definition_json) as TeamDefinition) : null;
      } catch {
        return null;
      }
    })();
    const member = def?.members?.find((m) => m.agent_id === agentKey || m.name === agentKey);
    return {
      agent_key: agentKey,
      name: member?.name || agentKey,
      role: member?.role || '',
    };
  }

  function sessionContextHandlers(sessionId: string) {
    return {
      onSessionContextPatch: (sid: string, patch: Parameters<typeof deps.sessionStore.patchSessionMetricsLocal>[1]) => {
        deps.sessionStore.patchSessionMetricsLocal(sid, patch);
      },
      onCompressNotice: (sid: string, prevRatio: number, newRatio: number) => {
        deps.onCompressNotice?.(sid, prevRatio, newRatio);
      },
      getSessionMetrics: (sid: string) => {
        const row = deps.sessionStore.findSessionById(sid);
        if (!row) return undefined;
        return {
          total_tokens: row.total_tokens,
          max_context_used_ratio: row.max_context_used_ratio,
          input_tokens: row.input_tokens,
          output_tokens: row.output_tokens,
        };
      },
    };
  }

  function ensureChatStream(sessionId: string) {
    if (chatStream && chatStreamSessionId === sessionId) {
      // Only sync wsConnected→true when the stream reports connected;
      // never downgrade to false here — onDisconnected is the authoritative
      // source for disconnection and avoids stale ref reads after onError.
      if (chatStream.connected.value) {
        deps.runtimeStore.setWsConnected(sessionId, true);
      }
      if (!chatStream.connected.value) {
        chatStream.connect();
      }
      return chatStream;
    }
    // B-02: Clean up previous stream's timeout & batch writer before creating
    // a new one, preventing the stale timeout from firing on the new session.
    chatStreamCleanup?.();
    chatStreamCleanup = null;
    chatStream?.disconnect();
    deps.runtimeStore.setWsConnected(sessionId, false);
    // New stream: reset progress accumulator so we don't leak envelopes from
    // a prior turn into the current one.
    clearProgress();

    chatStream = createChatStream(sessionId, {
      lastEventId: getChannelWsCursor(sessionId),
      onConnected: () => {
        deps.runtimeStore.setWsConnected(sessionId, true);
        void deps.refreshRunStatus(sessionId);
      },
      onDisconnected: () => {
        deps.runtimeStore.setWsConnected(sessionId, false);
      },
      onServerShutdown: () => {
        $q.notify({
          type: 'warning',
          message: t('chat.serverShutdown', '服务器已关闭，请重新登录'),
          timeout: 0,
          actions: [{ label: t('chat.relogin', '重新登录'), color: 'white', handler: () => {} }],
        });
        const auth = useAuthStore();
        auth.user = null;
        auth.sessionChecked = true;
        router.push({ name: 'login' });
      },
      onReplayState: (replaying) => {
        wsReplaying.value = replaying;
      },
      onReconnectFailed: () => {
        $q.notify({
          type: 'negative',
          message: t('chat.reconnectFailed', '连接已断开，请刷新页面重试'),
          timeout: 0,
          actions: [{ label: t('chat.refresh', '刷新页面'), color: 'white', handler: () => window.location.reload() }],
        });
      },
    });

    chatStreamCleanup = bindStreamHandlers(
      chatStream,
      {
        sessionId,
        resolveActiveSessionId: () => deps.sessionStore.selectedSession?.id ?? null,
        getMessages: (sid) => deps.messageStore.getMessages(sid),
        setMessages: (sid, rows) => deps.messageStore.setMessages(sid, rows),
        markSendingDone: deps.markSendingDone,
        clearSendingTimeout: deps.clearSendingTimeout,
        // Reset the progress accumulator when a new run is accepted so a new
        // turn starts with a clean timeline (avoids leaking the previous
        // turn's orchestration steps into the next one).
        onRunAccepted: () => {
          clearProgress();
          deps.onRunAccepted();
        },
        onRunStatus: deps.onRunStatus,
        onErrorNotify: notifyError,
        onOrchestrationNotice: notifyOrchestration,
        onReloadAfterCompletion: reloadSessionMessagesAfterCompletion,
        ...sessionContextHandlers(sessionId),
        onRunActivity: deps.touchRunActivity,
        onFirstByteArrived: deps.onFirstByteArrived,
        onExecutionProgress: pushProgress,
        // T1.6: Real-time AF — route activity envelopes directly to the
        // timeline handler for immediate UI updates.
        onActivityEnvelope: deps.onActivityEnvelope,
      },
      { batched: true },
    );

    chatStream.connect();
    chatStreamSessionId = sessionId;
    return chatStream;
  }

  function ensureTeamStream(sessionId: string) {
    if (teamStream && teamStreamSessionId === sessionId) {
      // Only sync wsConnected→true; never downgrade — onDisconnected is authoritative.
      if (teamStream.connected.value) {
        deps.runtimeStore.setWsConnected(sessionId, true);
      }
      // B-01: Reconnect if the transport exists but is disconnected.
      if (!teamStream.connected.value) {
        teamStream.connect();
      }
      return teamStream;
    }
    // B-02: Clean up previous stream's timeout & batch writer before creating
    // a new one, preventing the stale timeout from firing on the new session.
    teamStreamCleanup?.();
    teamStreamCleanup = null;
    teamStream?.disconnect();
    deps.runtimeStore.setWsConnected(sessionId, false);
    // New team stream: also reset progress accumulator so we don't leak
    // envelopes from a prior turn (or a different session kind) into the
    // current one.
    clearProgress();

    teamStream = createTeamStream(sessionId, {
      onReplayState: (replaying) => {
        wsReplaying.value = replaying;
      },
      onReconnectFailed: () => {
        $q.notify({
          type: 'negative',
          message: t('chat.reconnectFailed', '连接已断开，请刷新页面重试'),
          timeout: 0,
          actions: [{ label: t('chat.refresh', '刷新页面'), color: 'white', handler: () => window.location.reload() }],
        });
      },
      onServerShutdown: () => {
        $q.notify({
          type: 'warning',
          message: t('chat.serverShutdown', '服务器已关闭，请重新登录'),
          timeout: 0,
          actions: [{ label: t('chat.relogin', '重新登录'), color: 'white', handler: () => {} }],
        });
        const auth = useAuthStore();
        auth.user = null;
        auth.sessionChecked = true;
        router.push({ name: 'login' });
      },
      onConnected: () => {
        deps.runtimeStore.setWsConnected(sessionId, true);
        void deps.refreshRunStatus(sessionId);
      },
    });

    teamStreamCleanup = bindStreamHandlers(teamStream, {
      sessionId,
      resolveActiveSessionId: () => deps.sessionStore.teamSelectedSessionId,
      getMessages: (sid) => deps.messageStore.getMessages(sid),
      setMessages: (sid, rows) => deps.messageStore.setMessages(sid, rows),
      markSendingDone: deps.markSendingDone,
      clearSendingTimeout: deps.clearSendingTimeout,
      // Mirror chat stream: a new team run means a new turn — drop the
      // progress accumulator to avoid cross-turn envelope leakage.
      onRunAccepted: () => {
        clearProgress();
        deps.onRunAccepted();
      },
      onRunStatus: deps.onRunStatus,
      onErrorNotify: notifyError,
      onOrchestrationNotice: notifyOrchestration,
      onReloadAfterCompletion: reloadSessionMessagesAfterCompletion,
      ...sessionContextHandlers(sessionId),
      resolveMemberMeta: resolveTeamMemberMeta,
      onRunActivity: deps.touchRunActivity,
      onFirstByteArrived: deps.onFirstByteArrived,
      // Spirit / team sessions must also accumulate execution_progress so the
      // timeline shows inline orchestration / team / tool step cards
      // during the multi-agent fan-out. Mirrors the chat stream binding.
      onExecutionProgress: pushProgress,
      // T1.6: Real-time AF — route activity envelopes directly to the
      // timeline handler for immediate UI updates.
      onActivityEnvelope: deps.onActivityEnvelope,
    });

    teamStream.connect();
    teamStreamSessionId = sessionId;
    return teamStream;
  }

  function sendChatViaWs(stream: UseEnvelopeStreamReturn, upstream: WsUpstream): void {
    stream.connect();
    const transport = stream.transport.value;
    if (!transport) {
      throw new Error('WebSocket transport unavailable');
    }
    transport.send(upstream);
  }

  function disconnectChatStream() {
    if (chatStreamSessionId) {
      deps.runtimeStore.setWsConnected(chatStreamSessionId, false);
    }
    chatStreamCleanup?.();
    chatStreamCleanup = null;
    chatStream?.disconnect();
    chatStream = null;
    chatStreamSessionId = null;
  }

  function disconnectTeamStream() {
    if (teamStreamSessionId) {
      deps.runtimeStore.setWsConnected(teamStreamSessionId, false);
    }
    teamStreamCleanup?.();
    teamStreamCleanup = null;
    teamStream?.disconnect();
    teamStream = null;
    teamStreamSessionId = null;
  }

  function disconnectAll() {
    disconnectChatStream();
    disconnectTeamStream();
  }

  function cancelActiveStream() {
    chatStream?.cancel();
    teamStream?.cancel();
  }

  function patchAgentMessages(sessionId: string, streamId: string, env: Envelope, isDone: boolean) {
    deps.messageStore.setMessages(
      sessionId,
      patchStreamingEnvelope(deps.messageStore.getMessages(sessionId), sessionId, streamId, env, isDone),
    );
  }

  function subscribeSessionStream(
    sessionId: string,
    ownerKind: 'agent' | 'team',
    types: EnvelopeType[],
    handler: (env: Envelope) => void,
  ): () => void {
    const stream = ownerKind === 'team' ? ensureTeamStream(sessionId) : ensureChatStream(sessionId);
    return stream.onType(types, handler);
  }

  return {
    wsReplaying,
    executionProgress,
    ensureChatStream,
    ensureTeamStream,
    subscribeSessionStream,
    sendChatViaWs,
    disconnectChatStream,
    disconnectTeamStream,
    disconnectAll,
    cancelActiveStream,
    patchAgentMessages,
  };
}

/**
 * useConversationTimeline — 从 Activity 事件构建 ConversationTurn[]
 *
 * 单路径架构（Activity-First，T7.3a 已移除 Legacy 路径）：
 * - 当 activityRawRecords 非空时，从后端 Activity 事件构建 Turn，零推理。
 * - 无 AF 数据时，返回空数组（pre-AF 会话由 T6.3 回填保证有 AF 数据；
 *   AF API 失败时由 AF-GAP-05 显示错误提示）。
 *
 * 设计原则：
 * 1. AF 路径：按 turnId 分组 Activity 记录，构建完整 Think/Act/Say 时间线
 * 2. isFinal：Turn 内最后一个 SayActivity 的 isFinal=true
 */

import { computed, type ComputedRef, type Ref } from 'vue';
import type { Message } from '../types';
import type { Envelope } from '../../../realtime/envelope';
import type { ConversationTurn, AgentWorkProcess, Activity } from '../activityTimelineTypes';
import type { ReplyEvent, ThinkingEvent } from '../streamEventTypes';
import type { ActivityTreeNode } from '../activityTypes';
import type { AgentBlock, ProgressSection } from '../agentTreeTypes';
import { agentColorFromKey, ROOT_AGENT_KEY } from '../agentTreeTypes';
import { activityToStreamEvent } from './useActivityTimeline';
import { isTeamMemberOrigin, ensureOrigin } from '../messageOrigin';
import { mergeProgressEvents } from '../executionProgress';
import { useAppStore } from '../../../stores/app';

// ── UserTurn (internal) ──

interface UserTurn {
  userMessage: Message | null;
  messages: Message[];
}

// ── Helpers ──

/** 从 appStore.agents 按 agent_key 查询 agent.icon，用于补全 Activity 重建消息缺失的 icon。 */
function resolveAgentIconFromStore(agentKey: string): string {
  const key = agentKey?.trim();
  if (!key || key === ROOT_AGENT_KEY) return '';
  try {
    return useAppStore().agents.find((a) => a.agent_key === key)?.icon ?? '';
  } catch {
    return '';
  }
}

/** Build sorted ProgressSection[] from execution_progress envelopes, clamping startedAt to turn start. */
function buildProgressSections(
  progressByStep: Map<string, ProgressSection>,
  userMessage: Message | undefined,
): ProgressSection[] {
  if (progressByStep.size === 0) return [];
  const turnStartTs = userMessage?.created_at ? new Date(userMessage.created_at).getTime() : Date.now();
  const sections: ProgressSection[] = [];
  for (const section of progressByStep.values()) {
    // Clamp startedAt to turn start to avoid progress events appearing before the turn
    sections.push({ ...section, startedAt: Math.max(turnStartTs, section.startedAt) });
  }
  sections.sort((a, b) => a.startedAt - b.startedAt);
  return sections;
}

/** 按 role=user 边界划分消息为 UserTurn[]（turn 边界辅助函数，AF 唯一路径下使用） */
function splitByUserMessages(messages: Message[]): UserTurn[] {
  if (messages.length === 0) return [];
  const turns: UserTurn[] = [];
  let current: UserTurn = { userMessage: null, messages: [] };

  for (const msg of messages) {
    if (msg.role === 'user') {
      if (current.messages.length > 0 || current.userMessage) {
        turns.push(current);
      }
      current = { userMessage: msg, messages: [msg] };
    } else {
      current.messages.push(msg);
    }
  }

  if (current.messages.length > 0 || current.userMessage) {
    turns.push(current);
  }

  return turns;
}

// ── Main composable ──

export function useConversationTimeline(deps: {
  messages: ComputedRef<Message[]>;
  isTeamSession?: boolean;
  plannerKind?: ComputedRef<string>;
  progressEnvelopes?: ComputedRef<readonly Envelope[]>;
  activityTimelineActivities?: ComputedRef<readonly Activity[]>;
  activityAgentKey?: ComputedRef<string>;
  activityTaskContent?: ComputedRef<string | null>;
  activityTree?: ComputedRef<readonly ActivityTreeNode[]>;
  activityRawRecords?: ComputedRef<readonly import('../activityTypes').Activity[]>;
}) {
  // Per-turn memoization: historical turns keep the same object reference as
  // long as their inputs haven't changed. This avoids DynamicScroller / Vue
  // diffing the entire list on every streaming delta.
  const turnCache = new Map<string, { signature: string; turn: ConversationTurn }>();

  const conversationTurns = computed((): ConversationTurn[] => {
    const allMessages = deps.messages.value;
    if (allMessages.length === 0) {
      turnCache.clear();
      return [];
    }

    // Merge execution_progress envelopes into ProgressSection map
    const progressByStep = deps.progressEnvelopes?.value
      ? mergeProgressEvents(deps.progressEnvelopes.value)
      : new Map<string, ProgressSection>();

    const plannerKind = deps.plannerKind?.value ?? '';

    const afActivities = deps.activityTimelineActivities?.value;
    const afTree = deps.activityTree?.value;
    const afRawRecords = deps.activityRawRecords?.value;

    const ensured = allMessages.map(ensureOrigin);
    const userTurns = splitByUserMessages(ensured);
    if (userTurns.length === 0) return [];

    const activitiesByTurn = groupRawRecordsByTurn(afRawRecords ?? []);

    const agentKey = deps.activityAgentKey?.value || '';
    const taskContent = deps.activityTaskContent?.value || null;
    const activityTree = afTree ? [...afTree] : [];
    const activityTreeSig = computeActivityTreeSignature(activityTree);

    const result: ConversationTurn[] = [];
    const seenTurnKeys = new Set<string>();

    for (const turn of userTurns) {
      const userMessage = turn.userMessage || turn.messages.find((m) => m.role === 'user');
      const turnId = userMessage?.turn_id || turn.messages.find((m) => m.role === 'assistant')?.turn_id || '';
      const turnActivities = turnId ? activitiesByTurn.get(turnId) : undefined;

      const cacheKey = turnId || `turn-${userMessage?.id || 'no-user'}`;
      const signature = buildTurnSignature(turn, turnActivities ?? [], {
        agentKey,
        taskContent,
        activityTreeSig,
        progressByStep,
        plannerKind,
      });

      const cached = turnCache.get(cacheKey);
      if (cached && cached.signature === signature) {
        result.push(cached.turn);
        seenTurnKeys.add(cacheKey);
        continue;
      }

      const built = buildSingleTurnFromActivities(turn, turnActivities ?? [], {
        agentKey,
        taskContent,
        activityTree,
        progressByStep,
      });
      turnCache.set(cacheKey, { signature, turn: built });
      result.push(built);
      seenTurnKeys.add(cacheKey);
    }

    // Remove cache entries for turns that no longer exist (e.g. session switch).
    for (const key of turnCache.keys()) {
      if (!seenTurnKeys.has(key)) {
        turnCache.delete(key);
      }
    }

    return result;
  });

  return {
    conversationTurns,
    /** @deprecated AgentBlocks removed in AF refactoring — always empty */
    agentBlocks: computed((): AgentBlock[] => []),
  };
}

function groupRawRecordsByTurn(
  rawRecords: readonly import('../activityTypes').Activity[],
): Map<string, import('../activityTypes').Activity[]> {
  const map = new Map<string, import('../activityTypes').Activity[]>();
  for (const record of rawRecords) {
    const tid = record.turnId;
    if (!tid) continue;
    const group = map.get(tid);
    if (group) group.push(record);
    else map.set(tid, [record]);
  }
  return map;
}

function buildTurnSignature(
  turn: UserTurn,
  rawRecords: readonly import('../activityTypes').Activity[],
  opts: {
    agentKey: string;
    taskContent: string | null;
    activityTreeSig: string;
    progressByStep: Map<string, ProgressSection>;
    plannerKind: string;
  },
): string {
  const parts: string[] = [];
  parts.push(`u=${turn.userMessage?.id ?? 'n'}`);
  for (const m of turn.messages) {
    // Include content length and status; full content comparison is avoided
    // to keep signatures compact, while still catching meaningful changes.
    parts.push(`m=${m.id}:${m.status}:${m.turn_id}:${m.content_markdown.length}`);
  }
  parts.push(`r=${rawRecords.map((r) => `${r.id}:${r.status}:${r.kind}:${(r.content ?? '').length}`).join(',')}`);
  parts.push(`ak=${opts.agentKey}`);
  parts.push(`tc=${opts.taskContent ?? ''}`);
  parts.push(`pl=${opts.plannerKind}`);
  parts.push(`ps=${opts.progressByStep.size}`);
  parts.push(`at=${opts.activityTreeSig}`);
  return parts.join('|');
}

function computeActivityTreeSignature(tree: ActivityTreeNode[]): string {
  const parts: string[] = [];
  function walk(nodes: ActivityTreeNode[]) {
    for (const node of nodes) {
      parts.push(`${node.id}:${node.status}:${node.kind}`);
      walk(node.children);
    }
  }
  walk(tree);
  return parts.join(',');
}

// ── AF-FE-14: Build ALL ConversationTurns from raw Activity records ──

function buildAllConversationTurnsFromActivities(
  messages: Message[],
  rawRecords: readonly import('../activityTypes').Activity[],
  timelineActivities: readonly Activity[],
  opts: {
    agentKey: string;
    taskContent: string | null;
    activityTree: ActivityTreeNode[];
    progressByStep: Map<string, ProgressSection>;
    plannerKind: string;
  },
): ConversationTurn[] {
  const ensured = messages.map(ensureOrigin);
  const userTurns = splitByUserMessages(ensured);
  if (userTurns.length === 0) return [];

  // Group raw Activity records by turnId
  const activitiesByTurn = new Map<string, import('../activityTypes').Activity[]>();
  for (const record of rawRecords) {
    const tid = record.turnId;
    if (!tid) continue;
    const group = activitiesByTurn.get(tid);
    if (group) group.push(record);
    else activitiesByTurn.set(tid, [record]);
  }

  const result: ConversationTurn[] = [];

  for (const turn of userTurns) {
    const userMessage = turn.userMessage || turn.messages.find((m) => m.role === 'user');
    const turnId = userMessage?.turn_id || turn.messages.find((m) => m.role === 'assistant')?.turn_id || '';

    const turnActivities = turnId ? activitiesByTurn.get(turnId) : undefined;

    // 修复：即使没有 Activity 数据，也构建 turn（显示用户消息 + 等待指示器/失败状态）。
    // 这解决了"用户发送消息后 UI 无响应"的问题：
    // - 用户发送消息后，messageStore 有 pending-user 占位消息，但 Activity 数据尚未到达
    // - 原逻辑跳过无 Activity 数据的 turn，导致 UI 显示为空
    // - 新逻辑构建 turn，agentWork.status 根据消息状态设置为 'running' 或 'failed'
    // Pre-AF 会话由 T6.3 回填保证有 AF 数据；AF API 失败由 AF-GAP-05 显示错误提示。
    result.push(buildSingleTurnFromActivities(turn, turnActivities ?? [], opts));
  }

  return result;
}

function buildSingleTurnFromActivities(
  turn: UserTurn,
  rawRecords: readonly import('../activityTypes').Activity[],
  opts: {
    agentKey: string;
    taskContent: string | null;
    activityTree: ActivityTreeNode[];
    progressByStep: Map<string, ProgressSection>;
  },
): ConversationTurn {
  const userMessage = turn.userMessage || turn.messages.find((m) => m.role === 'user');
  const firstAssistant = turn.messages.find((m) => m.role === 'assistant' && !isTeamMemberOrigin(m.origin));

  // Build Activity tree from raw records for this turn
  const treeNodes = buildTreeFromRecords(rawRecords);
  const allNodes = flattenTree(treeNodes);
  let turnTimelineActivities: Activity[] = allNodes
    .filter((node) => node.kind !== 'task' && node.kind !== 'sub_task_board' && node.kind !== 'delegate')
    .map(activityToStreamEvent);

  // D3: Merge adjacent ThinkActivities
  turnTimelineActivities = mergeAdjacentThinkActivities(turnTimelineActivities);

  const rootTask = rawRecords.find((r) => r.kind === 'task');
  const agentKey = rootTask?.agentKey || opts.agentKey || firstAssistant?.agent_ref?.agent_key || ROOT_AGENT_KEY;
  const agentName = rootTask?.agentName || firstAssistant?.agent_ref?.name || '精灵助手';
  // 优先使用 message options_json 中的 agent.icon（后端 AssistantOptionsJSON 写入）；
  // 为空时回退到 appStore.agents 按 agent_key 查询（覆盖 Activity 重建消息 icon 缺失的场景）；
  // 仍为空时由 AgentAvatarQ 回退到 smart_toy 图标，与 AgentCard 保持一致。
  const refIcon = firstAssistant?.agent_ref?.icon || '';
  const agentIcon = refIcon || resolveAgentIconFromStore(agentKey);

  // Determine status from activities
  const hasRunning = rawRecords.some(
    (a) => a.status === 'running' || a.status === 'tool_running' || a.status === 'tool_blocked',
  );
  const hasFailedAction = rawRecords.some((a) => a.kind === 'action' && a.status === 'failed');
  const hasError = rawRecords.some((a) => a.kind === 'error');
  const rootTaskCompleted = rootTask?.status === 'completed';
  const lastSay = [...turnTimelineActivities].reverse().find((a) => a.kind === 'reply') as ReplyEvent | undefined;
  const hasResult = lastSay != null && !!lastSay.content;
  const isPartialFailure = hasFailedAction && rootTaskCompleted && hasResult;
  let status: AgentWorkProcess['status'];
  if (hasRunning) {
    status = 'running';
  } else if (hasError || (hasFailedAction && !hasResult)) {
    status = 'failed';
  } else if (rawRecords.length === 0) {
    // 修复：无 Activity 数据时，根据用户消息状态决定 agentWork.status
    // - pending-user 占位消息（status='ok'）→ 'running'（显示"正在思考…"等待指示器）
    // - 失败消息（status='failed'）→ 'failed'（显示失败状态）
    // 这确保用户发送消息后能立即看到 UI 反馈，而不是空白
    status = userMessage?.status === 'failed' ? 'failed' : 'running';
  } else {
    status = 'completed';
  }

  // Calculate duration
  const startTs = userMessage?.created_at ? new Date(userMessage.created_at).getTime() : 0;
  const lastMsg = turn.messages[turn.messages.length - 1];
  const endTs = lastMsg?.created_at ? new Date(lastMsg.created_at).getTime() : 0;
  const durationMs = startTs && endTs ? Math.max(0, endTs - startTs) : null;

  const progressSections = buildProgressSections(opts.progressByStep, userMessage);

  const agentWork: AgentWorkProcess = {
    agentKey,
    agentName,
    agentIcon,
    agentColor: agentColorFromKey(agentKey),
    status,
    durationMs,
    activities: turnTimelineActivities,
    activityTree: opts.activityTree,
    task: opts.taskContent || rootTask?.content || userMessage?.content_markdown || null,
    result: lastSay?.content || null,
    hasPartialFailure: isPartialFailure,
    plan: null,
    teamStatus: null,
    progressSections,
    startedAt: userMessage?.created_at || firstAssistant?.created_at || '',
    finishedAt: status !== 'running' ? lastMsg?.created_at || '' : null,
  };

  return {
    id: `turn-${userMessage?.id || 'no-user'}`,
    userMessage: userMessage ?? null,
    agentWork,
  };
}

function mergeAdjacentThinkActivities(activities: Activity[]): Activity[] {
  const result: Activity[] = [];
  let i = 0;
  while (i < activities.length) {
    const current = activities[i];
    if (current.kind !== 'thinking') {
      result.push(current);
      i++;
      continue;
    }
    const group: ThinkingEvent[] = [current as ThinkingEvent];
    while (i + 1 < activities.length && activities[i + 1].kind === 'thinking') {
      i++;
      group.push(activities[i] as ThinkingEvent);
    }
    if (group.length === 1) {
      result.push(group[0]);
    } else {
      const mergedContent = group
        .map((s) => s.content)
        .filter(Boolean)
        .join('\n\n');
      const totalDuration = group.reduce((sum, s) => sum + (s.durationMs ?? 0), 0) || null;
      const anyStreaming = group.some((s) => s.streaming);
      result.push({
        kind: 'thinking',
        id: group[0].id + '-merged',
        content: mergedContent,
        label: undefined,
        collapsed: !anyStreaming,
        streaming: anyStreaming,
        durationMs: totalDuration,
        subSteps: group,
      });
    }
    i++;
  }
  return result;
}

function buildTreeFromRecords(records: readonly import('../activityTypes').Activity[]): ActivityTreeNode[] {
  const nodeMap = new Map<string, ActivityTreeNode>();
  const roots: ActivityTreeNode[] = [];

  for (const record of records) {
    nodeMap.set(record.id, { ...record, children: [] });
  }

  for (const record of records) {
    const node = nodeMap.get(record.id)!;
    if (record.parentActivityId && nodeMap.has(record.parentActivityId)) {
      nodeMap.get(record.parentActivityId)!.children.push(node);
    } else {
      roots.push(node);
    }
  }

  const sortTree = (nodes: ActivityTreeNode[]) => {
    nodes.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
    for (const node of nodes) sortTree(node.children);
  };
  sortTree(roots);

  return roots;
}

function flattenTree(tree: ActivityTreeNode[]): ActivityTreeNode[] {
  const result: ActivityTreeNode[] = [];
  for (const node of tree) {
    result.push(node);
    result.push(...flattenTree(node.children));
  }
  return result;
}

import { onUnmounted, ref, type Ref } from 'vue';
import { useChatRuntimeStore } from '../../../stores/chat/runtimeStore';
import type { PendingMessage } from '../types';
import { messageQueuedFromEnvelope, type RunStatusFromWs } from '../envelopeRunStatus';
import type { Envelope } from '../envelope';

export function useFollowUpQueue(
  sessionId: Ref<string | undefined>,
  sending: Ref<boolean>,
  notifyError?: (message: string) => void,
) {
  const pendingMessages = ref<PendingMessage[]>([]);
  /** One-shot poll timer: fires once after run starts, then WS events take over. */
  let pendingPollTimer: ReturnType<typeof setTimeout> | null = null;

  async function refreshPendingMessages() {
    const sid = sessionId.value;
    if (!sid) {
      pendingMessages.value = [];
      return;
    }
    const runtime = useChatRuntimeStore();
    try {
      pendingMessages.value = await runtime.fetchPendingMessages(sid);
    } catch (err) {
      notifyError?.(err instanceof Error ? err.message : '加载排队消息失败');
      pendingMessages.value = [];
    }
  }

  function stopPendingPoll() {
    if (pendingPollTimer != null) {
      clearTimeout(pendingPollTimer);
      pendingPollTimer = null;
    }
  }

  /** Initial one-shot fetch after a short delay; subsequent updates come via WS events. */
  function scheduleInitialFetch() {
    stopPendingPoll();
    pendingPollTimer = setTimeout(() => {
      pendingPollTimer = null;
      void refreshPendingMessages();
    }, 500);
  }

  /** WS-driven refresh: called when a relevant envelope arrives.
   *  Replaces the old 3-second polling loop with real-time push. */
  function onRunStatusEnvelope(env: Envelope) {
    if (messageQueuedFromEnvelope(env)) {
      void refreshPendingMessages();
    }
    // Also refresh on run completion to clear stale pending items
    const meta = env.metadata ?? {};
    const rs = String(meta.status ?? '');
    if (rs === 'completed' || rs === 'cancelled' || rs === 'failed') {
      void refreshPendingMessages();
    }
  }

  async function onCancelPending(pendingId: string) {
    const sid = sessionId.value;
    if (!sid || !pendingId) return;
    const runtime = useChatRuntimeStore();
    try {
      const ok = await runtime.cancelPending(sid, pendingId);
      if (ok) {
        pendingMessages.value = pendingMessages.value.filter((pm) => pm.id !== pendingId);
      } else {
        notifyError?.('取消排队消息失败');
      }
    } catch (err) {
      notifyError?.(err instanceof Error ? err.message : '取消排队消息失败');
    }
  }

  async function onUpdatePending(pendingId: string, content: string) {
    const sid = sessionId.value;
    if (!sid || !pendingId || !content.trim()) return;
    const runtime = useChatRuntimeStore();
    try {
      const ok = await runtime.updatePending(sid, pendingId, content.trim());
      if (ok) {
        pendingMessages.value = pendingMessages.value.map((pm) =>
          pm.id === pendingId ? { ...pm, content: content.trim() } : pm,
        );
      } else {
        notifyError?.('更新排队消息失败');
      }
    } catch (err) {
      notifyError?.(err instanceof Error ? err.message : '更新排队消息失败');
    }
  }

  async function onInterruptPending(pendingId: string) {
    const sid = sessionId.value;
    if (!sid || !pendingId) return;
    const runtime = useChatRuntimeStore();
    try {
      const ok = await runtime.interruptAndSend(sid, pendingId);
      if (ok) {
        pendingMessages.value = pendingMessages.value.filter((pm) => pm.id !== pendingId);
      } else {
        notifyError?.('立即发送失败');
      }
    } catch (err) {
      notifyError?.(err instanceof Error ? err.message : '立即发送失败');
    }
  }

  function watchSending(active: boolean) {
    if (active) {
      // One-shot fetch after 500ms; WS events handle subsequent updates
      scheduleInitialFetch();
    } else {
      // Final refresh after run completes, then stop
      setTimeout(() => {
        void refreshPendingMessages();
      }, 1000);
    }
  }

  onUnmounted(stopPendingPoll);

  return {
    pendingMessages,
    refreshPendingMessages,
    onRunStatusEnvelope,
    onCancelPending,
    onInterruptPending,
    onUpdatePending,
    watchSending,
  };
}

import { computed } from 'vue';
import type { ComputedRef } from 'vue';
import type { Message } from '../../../domain/types';
import type { ToolUseEvent } from '../types';
import type { TodoItem, TodoBoardState } from '../agentTreeTypes';
import { toolEventFromMessage } from '../envelopeToolCall';

/** Simple hash from string to stable hex id (8 chars). */
function contentHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

interface RawTodoItem {
  content: string;
  activeForm: string;
  status: string;
  id?: string;
}

interface TodoWriteOutput {
  todos: RawTodoItem[];
}

export interface TodoBoardEntry {
  agentKey: string;
  agentName: string;
  board: TodoBoardState;
}

function parseTodoItems(raw: unknown): TodoItem[] {
  if (!raw || typeof raw !== 'object') return [];
  const output = raw as TodoWriteOutput;
  if (!Array.isArray(output.todos)) return [];
  return output.todos
    .filter((t) => t && t.content && t.status)
    .map((t) => ({
      id: t.id || contentHash(t.content),
      content: t.content,
      activeForm: t.activeForm ?? '',
      status: t.status as TodoItem['status'],
      updatedAt: new Date().toISOString(),
    }));
}

/**
 * Composable that scans messages for the last successful `todo_write`
 * tool result and derives a TodoBoardState from it.
 */
export function useTodoBoard(messages: ComputedRef<Message[]>) {
  const todoBoardState = computed<TodoBoardState | null>(() => {
    const msgs = messages.value;
    if (!msgs || msgs.length === 0) return null;

    // Walk messages in reverse to find the last successful todo_write
    for (let i = msgs.length - 1; i >= 0; i--) {
      const msg = msgs[i];
      const ev = toolEventFromMessage(msg);
      if (!ev) continue;
      if (ev.tool_name !== 'todo_write') continue;
      if (ev.status !== 'success') continue;
      if (!ev.result) continue;

      const items = parseTodoItems(ev.result);
      if (items.length === 0) continue;

      return {
        todos: items,
        lastUpdated: ev.occurred_at || new Date().toISOString(),
        source: 'tool_result' as const,
      };
    }

    return null;
  });

  return { todoBoardState };
}

import type { Envelope } from './envelope';
import type { ActivityKind, ToolUseEvent } from './types';
import type { Message } from './types';
import { MESSAGE_STATUS } from '../../domain/types';
import { canonicalToolStatus, messageStatusFromWire } from './lib/statusMap';
import { activityMessageId } from './lib/activityMessageId';
import { isToolUseEvent } from './lib/isToolUseEvent';
import { toolEventToMessage } from './toolEventMarkdown';

/**
 * Maximum byte length for an individual `arguments_json` / `result_json` payload
 * we will decode. Anything larger is truncated to a preview that mirrors the
 * backend `biz.redactActivityJSON` (512 bytes) so the chat UI and the
 * Observatory chrome stay consistent and a single LLM payload can't blow up
 * the browser (SEC-04-style payload-bomb protection).
 */
const ACTIVITY_JSON_PREVIEW_LIMIT = 512;

function truncatePreview(raw: string): string {
  const trimmed =
    raw.length > ACTIVITY_JSON_PREVIEW_LIMIT ? raw.slice(0, ACTIVITY_JSON_PREVIEW_LIMIT) + '…[truncated]' : raw;
  return trimmed;
}

function parseJSONRecord(raw: string | undefined): Record<string, unknown> {
  if (!raw?.trim()) return {};
  const preview = truncatePreview(raw);
  try {
    const v = JSON.parse(preview) as unknown;
    if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
      return v as Record<string, unknown>;
    }
    // Preserve arrays and primitive JSON values verbatim under a known key so
    // downstream consumers (Vue props, JSON.stringify in buildToolSection) keep
    // their structure. Without this, LLM-emitted array arguments were collapsed
    // to { value: [...] } and lost their shape in the UI.
    if (Array.isArray(v)) return { __array: v };
    if (v === null) return { __null: true };
    return { __value: v };
  } catch {
    return { __raw: preview };
  }
}

// Re-export the canonical implementation from ./lib/activityMessageId.
export { activityMessageId };

// Kept as a thin wrapper so existing call sites (and test mocks) that import
// `normalizeToolStatus` continue to work. The single source of truth now lives
// in ./lib/statusMap.
function normalizeToolStatus(status: string): ToolUseEvent['status'] {
  return canonicalToolStatus(status);
}

/** Strip the wrapper keys produced by {@link parseJSONRecord} so callers see the
 *  original JSON value (array, null, primitive) instead of the synthetic object. */
function unwrapParsed(record: Record<string, unknown>): unknown {
  const keys = Object.keys(record);
  if (keys.length === 1) {
    if (keys[0] === '__array') return record.__array;
    if (keys[0] === '__value') return record.__value;
    if (keys[0] === '__null') return null;
  }
  return record;
}

/** Build a {@link ToolUseEvent} from a tool_call / tool_result Envelope. */
export function envelopeToToolEvent(env: Envelope, phase: 'before' | 'after'): ToolUseEvent | null {
  const tc = env.tool_call;
  if (!tc?.name && !tc?.id) return null;
  const args = unwrapParsed(parseJSONRecord(tc.arguments_json)) as ToolUseEvent['arguments'];
  const resultRecord = parseJSONRecord(tc.result_json);
  const result = unwrapParsed(resultRecord) as Record<string, unknown> | null | undefined;
  const toolName = tc.name || 'tool';
  // AF-Phase3: activity_kind is always provided by the backend ActivityProjector.
  // Default to 'tool' when missing (legacy envelopes only).
  const kind = (tc.activity_kind || 'tool') as ActivityKind;
  // Resolve the user-facing error message with the following precedence:
  //   1) result.error (string body)            — most descriptive
  //   2) error_code, but only if the tool actually failed
  //   3) undefined
  // The status check covers both 'failed' and 'error' (backend tool_invocation_recorder.go
  // emits "error" — see internal/agent/tool_invocation_recorder.go:40). Without the
  // multi-value check, the error_code fallback was unreachable and the user saw
  // an empty error section.
  const status = normalizeToolStatus(tc.status || (phase === 'before' ? 'running' : 'success'));
  const isFailure = status === 'failed';
  const resultErrorStr =
    typeof result === 'object' && result !== null && typeof (result as { error?: unknown }).error === 'string'
      ? (result as { error: string }).error
      : undefined;
  const resultI18nKey =
    typeof result === 'object' && result !== null && typeof (result as { i18n_key?: unknown }).i18n_key === 'string'
      ? (result as { i18n_key: string }).i18n_key
      : undefined;
  const errorMessage = resultErrorStr ?? (isFailure && tc.error_code ? tc.error_code : undefined);
  return {
    id: tc.id || env.id,
    phase,
    status,
    agent_id: tc.agent_id || '',
    agent_key: tc.agent_key || env.author || '',
    agent_name: tc.agent_name || env.author || 'Agent',
    tool_name: toolName,
    tool_label: tc.display_label || tc.name,
    arguments: args,
    result:
      phase === 'after' || (result && typeof result === 'object' && Object.keys(result).length > 0)
        ? (result as Record<string, unknown>)
        : undefined,
    error: errorMessage,
    occurred_at: tc.finished_at || tc.started_at || env.timestamp || new Date().toISOString(),
    duration_ms: tc.duration_ms,
    is_long_running: tc.is_long_running,
    activity_kind: kind,
    display_label: tc.display_label,
    icon_key: tc.icon_key,
    summary: tc.summary,
    started_at: tc.started_at,
    finished_at: tc.finished_at,
    error_code: tc.error_code,
    i18n_key: resultI18nKey,
    run_id: tc.run_id,
    trace_id: tc.trace_id,
  };
}

export function mergeToolEvents(existing: ToolUseEvent, incoming: ToolUseEvent): ToolUseEvent {
  return {
    ...existing,
    ...incoming,
    id: incoming.id || existing.id,
    phase: incoming.phase || existing.phase,
    status: incoming.status || existing.status,
    tool_name: incoming.tool_name || existing.tool_name,
    tool_label: incoming.display_label || incoming.tool_label || existing.tool_label,
    display_label: incoming.display_label || existing.display_label,
    icon_key: incoming.icon_key || existing.icon_key,
    summary: incoming.summary || existing.summary,
    activity_kind: incoming.activity_kind || existing.activity_kind,
    arguments: Object.keys(incoming.arguments ?? {}).length > 0 ? incoming.arguments : existing.arguments,
    result: incoming.result ?? existing.result,
    error: incoming.error || existing.error,
    duration_ms: incoming.duration_ms ?? existing.duration_ms,
    is_long_running: incoming.is_long_running ?? existing.is_long_running,
    started_at: incoming.started_at || existing.started_at,
    finished_at: incoming.finished_at || existing.finished_at,
    error_code: incoming.error_code || existing.error_code,
    i18n_key: incoming.i18n_key || existing.i18n_key,
    run_id: incoming.run_id || existing.run_id,
    trace_id: incoming.trace_id || existing.trace_id,
    agent_key: incoming.agent_key || existing.agent_key,
    agent_id: incoming.agent_id || existing.agent_id,
    agent_name: incoming.agent_name || existing.agent_name,
    occurred_at: incoming.occurred_at || existing.occurred_at,
  };
}

export function upsertToolMessage(
  messages: Message[],
  sessionId: string,
  env: Envelope,
  phase: 'before' | 'after',
): Message[] {
  const event = envelopeToToolEvent(env, phase);
  if (!event) return messages;
  const row = toolEventToMessage(sessionId, event);
  const messageId = activityMessageId(event);
  row.id = messageId;
  const idx = messages.findIndex((m) => m.id === messageId || (event.id && m.id === `act-${event.id}`));
  if (idx >= 0) {
    const priorMeta = toolEventFromMessage(messages[idx]);
    const merged = priorMeta ? mergeToolEvents(priorMeta, event) : event;
    const nextRow = toolEventToMessage(sessionId, merged);
    nextRow.id = messageId;
    const next = [...messages];
    next[idx] = { ...messages[idx], ...nextRow, id: messageId };
    return next;
  }
  return [...messages, row];
}

/** Mark in-flight tool activity rows as cancelled when run_status=cancelled. */
export function cancelRunningToolMessages(messages: Message[], reason = '用户已停止生成'): Message[] {
  return patchOrphanToolMessages(messages, reason, 'cancelled', MESSAGE_STATUS.TOOL_CANCELLED, [
    MESSAGE_STATUS.TOOL_RUNNING,
    MESSAGE_STATUS.TOOL_BLOCKED,
  ]);
}

/** Mark orphan in-flight tool rows when a turn ends without tool_result. */
export function finalizeOrphanToolMessages(
  messages: Message[],
  reason = 'Turn 已完成，未收到工具结果',
  statuses: string[] = [MESSAGE_STATUS.TOOL_RUNNING, MESSAGE_STATUS.TOOL_BLOCKED],
): Message[] {
  return patchOrphanToolMessages(messages, reason, 'failed', MESSAGE_STATUS.TOOL_FAILED, statuses);
}

function patchOrphanToolMessages(
  messages: Message[],
  reason: string,
  eventStatus: ToolUseEvent['status'],
  messageStatus: string,
  statuses: string[],
): Message[] {
  const allowed = new Set(statuses);
  let changed = false;
  const next = messages.map((msg) => {
    if (!allowed.has(msg.status || '')) return msg;
    const event = toolEventFromMessage(msg);
    if (!event) return msg;
    changed = true;
    const patched: ToolUseEvent = {
      ...event,
      status: eventStatus,
      phase: 'after',
      error: event.error || reason,
      finished_at: new Date().toISOString(),
    };
    const row = toolEventToMessage(msg.session_id, patched);
    row.id = msg.id;
    return { ...msg, ...row, id: msg.id, status: messageStatus };
  });
  return changed ? next : messages;
}

/**
 * Cache for {@link toolEventFromMessage} parsed results, keyed by `message.id`.
 *
 * Only used for the `JSON.parse(options_json)` fallback path — messages with
 * `tool_event` already set take the fast path and bypass this cache entirely.
 *
 * Invalidation: {@link clearToolEventCache} is called from `messageStore` on
 * session switch / message reload / message clear, so stale entries from a
 * previous server load cannot leak into a new session's view.
 */
const toolEventCache = new Map<string, ToolUseEvent | null>();

export function toolEventFromMessage(message: Message): ToolUseEvent | null {
  // `tool_event` is typed as `unknown` on the cross-domain Message facade.
  // Run the candidate through isToolUseEvent so the cast is structural, not
  // a blind `as ToolUseEvent` (regression: corrupted / partial objects were
  // leaking through as "valid" tool events).
  if (isToolUseEvent(message.tool_event)) {
    return message.tool_event;
  }
  // Cache lookup (only for the JSON.parse fallback path). Skip cache when
  // message.id is missing — those rows are ephemeral and cannot be safely
  // keyed.
  const cacheKey = message.id || '';
  if (cacheKey) {
    const cached = toolEventCache.get(cacheKey);
    if (cached !== undefined) {
      return cached;
    }
  }
  let result: ToolUseEvent | null = null;
  try {
    const raw = JSON.parse(message.options_json || '{}') as { tool_event?: unknown };
    if (isToolUseEvent(raw.tool_event)) {
      result = raw.tool_event;
    }
  } catch {
    result = null;
  }
  if (cacheKey) {
    toolEventCache.set(cacheKey, result);
  }
  return result;
}

/**
 * Clear the {@link toolEventCache}. Call from `messageStore` on session switch,
 * message reload, or message clear to prevent stale parsed results from a
 * previous server load (server may update `options_json` for the same id).
 *
 * @param messageIds When provided, removes only the given ids; otherwise
 *                   clears the entire cache.
 */
export function clearToolEventCache(messageIds?: string[]): void {
  if (!messageIds) {
    toolEventCache.clear();
    return;
  }
  for (const id of messageIds) {
    toolEventCache.delete(id);
  }
}

import type { Message } from './types';
import { normalizeServerMessageOptions } from './streamContentPatch';
import { parseMessageOptions } from './parseMessageOptions';
import { isInFlightStatus } from '../../domain/types';
import {
  ensureOrigin,
  isEphemeralOrigin,
  isInFlightOrigin,
  isPendingUserOrigin,
  isStreamingOrigin,
  isTeamMemberOrigin,
} from './messageOrigin';

function normalizeMessage(m: Message): Message {
  const withOrigin = ensureOrigin(m);
  const normalized = { ...withOrigin, options_json: normalizeServerMessageOptions(withOrigin.options_json ?? '') };
  const parsed = parseMessageOptions(normalized.options_json);
  return { ...normalized, ...parsed };
}

function isEphemeralMessage(message: Message): boolean {
  return isEphemeralOrigin(message.origin);
}

/** Whether this row is a local-only in-flight message (not yet persisted by server). */
export function isInFlightLocalRow(message: Message): boolean {
  // Finalized snapshots (streaming_snapshot origin) — treat as persisted for sorting.
  // T7.3b: Covers AF mode finalized messages (actv-* upgraded to streaming_snapshot
  // by finalizeStreamingMessageFromDone).
  if (message.origin?.kind === 'streaming_snapshot') return false;
  // Reconstructed action messages (tool_activity origin with terminal status)
  // are finalized snapshots from Activity API data — treat as persisted for sorting.
  if (message.origin?.kind === 'tool_activity' && !isInFlightStatus(message.status || '')) return false;
  if (isEphemeralMessage(message)) return true;
  return isInFlightStatus(message.status || '');
}

/**
 * Whether a local-only message should be included in the merge output.
 *
 * Messages fall into three categories for merge purposes:
 *   1. **persisted** — has a server counterpart, managed by server data
 *   2. **in-flight-active** — still streaming/running, must be preserved
 *   3. **af-finalized** — Activity-First mode messages (streaming_snapshot
 *      origin) that have been finalized. These carry per-round content
 *      from Activity events and must be preserved when
 *      excludeMergedAssistant=true, because the server's merged assistant
 *      ChatMessage is excluded.
 */
function shouldIncludeInMerge(message: Message, excludeMergedAssistant: boolean): boolean {
  // Streaming snapshots: finalized local snapshots carrying round-separated content
  if (message.origin?.kind === 'streaming_snapshot' && excludeMergedAssistant) return true;
  return isInFlightLocalRow(message);
}

function messageOrder(message: Message): [number, string] {
  // Finalized local messages (streaming_snapshot origin) sort alongside
  // persisted messages by timestamp, not pushed to the end with active in-flight.
  if (message.origin?.kind === 'streaming_snapshot') return [0, message.created_at || ''];
  // Reconstructed action messages (tool_activity origin with terminal status)
  // sort alongside persisted messages to maintain thinking → action → reply order.
  if (message.origin?.kind === 'tool_activity' && !isInFlightStatus(message.status || ''))
    return [0, message.created_at || ''];
  const inFlight = isInFlightLocalRow(message) ? 1 : 0;
  return [inFlight, message.created_at || ''];
}

/**
 * Compare two ISO 8601 timestamps numerically via Date.parse.
 * Falls back to string comparison when either timestamp is unparseable,
 * ensuring stable ordering even with mixed precision (seconds / milliseconds / microseconds).
 */
function compareTimestamps(a: string, b: string): number {
  if (!a && !b) return 0;
  if (!a) return -1;
  if (!b) return 1;
  const ta = Date.parse(a);
  const tb = Date.parse(b);
  if (Number.isNaN(ta) || Number.isNaN(tb)) {
    // Fallback: string comparison for non-standard formats
    return a < b ? -1 : a > b ? 1 : 0;
  }
  if (ta !== tb) return ta - tb;
  // Same millisecond — compare sub-millisecond precision via string to preserve
  // microsecond ordering (e.g. addMicroOffset timestamps).
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Drop optimistic user placeholders after the server turn completes. */
export function dropPendingUserPlaceholders(messages: Message[]): Message[] {
  return messages.filter((m) => !isPendingUserOrigin(m.origin));
}

function shouldDropStaleInFlight(message: Message): boolean {
  const origin = message.origin;
  if (isPendingUserOrigin(origin)) return message.status !== 'failed';
  if (isStreamingOrigin(origin)) {
    // streaming_snapshot messages (AF mode finalized) represent correctly
    // separated LLM round content. They must NOT be dropped during merge,
    // because the server-persisted assistant message contains ALL rounds'
    // content merged into one, and dropping snapshots would lose the round
    // separation.
    if (origin?.kind === 'streaming_snapshot') return false;
    return !isInFlightStatus(message.status || '');
  }
  if (isTeamMemberOrigin(origin)) return false;
  return isInFlightStatus(message.status || '');
}

/**
 * Merge incremental server rows into existing session state without dropping persisted history.
 * Used by `loadMessages({ afterRevision })` where the API returns only new messages.
 */
export function mergeIncrementalSessionMessages(
  incremental: Message[],
  local: Message[],
  opts?: { dropStaleInFlight?: boolean },
): Message[] {
  if (incremental.length === 0) return local;
  const normalizedIncremental = incremental.map(normalizeMessage);
  const persisted = local.filter((m) => !isInFlightLocalRow(m));
  const byId = new Map(persisted.map((m) => [m.id, m]));
  for (const row of normalizedIncremental) {
    byId.set(row.id, row);
  }
  return mergeSessionMessages([...byId.values()], local, opts);
}

const PENDING_MATCH_TIME_WINDOW_MS = 30_000;

/** Match a pending-user placeholder to a server-persisted user message by content. */
function isPendingUserMatch(pending: Message, serverUser: Message): boolean {
  if (!isPendingUserOrigin(pending.origin)) return false;
  if (pending.role !== 'user' || serverUser.role !== 'user') return false;
  if (pending.session_id !== serverUser.session_id) return false;
  if (pending.content_markdown !== serverUser.content_markdown) return false;

  if (pending.turn_number > 0 && serverUser.turn_number > 0 && pending.turn_number !== serverUser.turn_number) {
    return false;
  }

  const pendingTime = new Date(pending.created_at).getTime();
  const serverTime = new Date(serverUser.created_at).getTime();
  if (Number.isFinite(pendingTime) && Number.isFinite(serverTime)) {
    if (Math.abs(pendingTime - serverTime) > PENDING_MATCH_TIME_WINDOW_MS) return false;
  }

  return true;
}

/** Build a map from (sessionId, role=user, content) → server message for fast lookup. */
function buildServerUserContentMap(server: Message[]): Map<string, Message[]> {
  const map = new Map<string, Message[]>();
  for (const m of server) {
    if (m.role !== 'user') continue;
    const key = `${m.session_id}::${m.content_markdown}`;
    const arr = map.get(key) ?? [];
    arr.push(m);
    map.set(key, arr);
  }
  return map;
}

function findServerMatchForPending(
  pending: Message,
  serverMap: Map<string, Message[]>,
  matched: Set<string>,
): Message | null {
  const key = `${pending.session_id}::${pending.content_markdown}`;
  const candidates = serverMap.get(key);
  if (!candidates) return null;
  for (const c of candidates) {
    if (!matched.has(c.id)) {
      matched.add(c.id);
      return c;
    }
  }
  return null;
}

/** Merge server history with in-flight WS rows (streaming text, running tool cards). */
export function mergeSessionMessages(
  server: Message[],
  local: Message[],
  opts?: { dropStaleInFlight?: boolean },
): Message[] {
  const normalizedServer = server.map(normalizeMessage);
  if (local.length === 0) return normalizedServer;
  const serverById = new Map(normalizedServer.map((m) => [m.id, m]));
  const serverUserByContent = buildServerUserContentMap(normalizedServer);

  // Determine whether to exclude the server's merged assistant message.
  //
  // excludeMergedAssistant is only true when we actually have local
  // streaming_snapshot assistant messages to replace the server's merged
  // content. This is a safety guard: if no snapshots exist (e.g. AF API
  // failed and returned no data), falling back to the server's merged
  // message prevents a blank UI.
  //
  // T7.3b: Legacy ws-snap-* references removed. streaming_snapshot origin
  // now covers both AF mode finalized messages (actv-*) and any remaining
  // snapshot messages. The hasSnapshots guard is retained as an AF safety
  // fallback, not Legacy logic.
  //
  // Trigger for hasSnapshots:
  //   Activity-First mode: Activity events/data provide complete per-round
  //   content (thinking/reply/action). The server-persisted assistant
  //   ChatMessage merges ALL rounds into one — including it would duplicate
  //   Activity content and cause the UI to show a single merged block
  //   instead of correctly separated rounds.
  const hasSnapshots = local.some((m) => m.origin?.kind === 'streaming_snapshot' && m.role === 'assistant');
  const excludeMergedAssistant = hasSnapshots;

  const pendingReplacedBy = new Map<string, Message>();
  const matchedServerIDs = new Set<string>();
  for (const row of local) {
    if (!isPendingUserOrigin(row.origin) || row.role !== 'user') continue;
    if (row.status === 'failed') continue;
    const serverMatch = findServerMatchForPending(row, serverUserByContent, matchedServerIDs);
    if (serverMatch) {
      pendingReplacedBy.set(row.id, serverMatch);
    }
  }

  // When excluding merged assistant messages, identify server assistant
  // messages that are NOT activity messages (tool cards). These "main"
  // assistant messages contain ALL rounds merged into one — including them
  // would duplicate Activity/snapshot content.
  //
  // Tool activity messages (act-*, schema=chat.activity/v1) must NOT
  // be excluded: they contain tool call details (name/args/result) that are
  // distinct from the reasoning/text in Activities/snapshots.
  const serverMainAssistantIds = new Set<string>();
  if (excludeMergedAssistant) {
    for (const m of normalizedServer) {
      if (m.role === 'assistant' && !isActivityMessage(m)) {
        serverMainAssistantIds.add(m.id);
      }
    }
  }

  const merged: Message[] = [];
  for (const srv of normalizedServer) {
    // Skip server main assistant messages when Activity data or snapshots
    // provide correctly separated per-round content
    if (excludeMergedAssistant && serverMainAssistantIds.has(srv.id)) continue;
    merged.push(srv);
  }
  for (const row of local) {
    if (pendingReplacedBy.has(row.id)) continue;
    if (serverById.has(row.id)) continue;
    if (!shouldIncludeInMerge(row, excludeMergedAssistant)) continue;
    if (opts?.dropStaleInFlight && shouldDropStaleInFlight(row)) continue;
    merged.push(row);
  }
  merged.sort((a, b) => {
    const [inFlightA, timeA] = messageOrder(a);
    const [inFlightB, timeB] = messageOrder(b);
    if (inFlightA !== inFlightB) return inFlightA - inFlightB;
    return compareTimestamps(timeA, timeB);
  });
  return merged;
}

export function isActivityMessage(message: Message): boolean {
  if (message.tool_event) return true;
  try {
    const raw = JSON.parse(message.options_json || '{}') as { schema?: string; tool_event?: unknown };
    return raw.schema === 'chat.activity/v1' || Boolean(raw.tool_event);
  } catch {
    return message.status.startsWith('tool_');
  }
}

import type { Message, MessageOrigin } from '../../domain/types';

export type { MessageOrigin };

/**
 * Derive MessageOrigin from a message ID using prefix conventions.
 *
 * This is a **migration bridge**: existing in-flight messages still carry
 * prefix-based IDs (pending-user-*, member-*, act-*, tool-*).
 * Once all message creation sites set `origin` explicitly at construction time,
 * this function can be removed and `ensureOrigin` can simply assert `message.origin`.
 *
 * Migration plan: after streamHandlers / toolEventMarkdown always set origin,
 * flip `ensureOrigin` to throw on missing origin, then remove `originFromId`.
 */
export function originFromId(id: string, role: string): MessageOrigin {
  if (id.startsWith('pending-user-')) return { kind: 'pending_user', localId: id };
  if (id.startsWith('actv-')) return { kind: 'streaming', sessionId: '' };
  if (id.startsWith('ws-stream-')) return { kind: 'streaming', sessionId: '' };
  if (id.startsWith('member-')) return { kind: 'team_member', agentKey: id.replace(/^member-/, '') };
  if (id.startsWith('act-') || id.startsWith('tool-')) return { kind: 'tool_activity', toolEventId: id };
  return { kind: 'persisted' };
}

export function isEphemeralOrigin(origin: MessageOrigin | undefined): boolean {
  if (!origin) return false;
  return origin.kind !== 'persisted';
}

export function isInFlightOrigin(origin: MessageOrigin | undefined): boolean {
  if (!origin) return false;
  return (
    origin.kind === 'pending_user' ||
    origin.kind === 'streaming' ||
    origin.kind === 'streaming_snapshot' ||
    origin.kind === 'tool_activity'
  );
}

export function isPendingUserOrigin(origin: MessageOrigin | undefined): boolean {
  return origin?.kind === 'pending_user';
}

export function isStreamingOrigin(origin: MessageOrigin | undefined): boolean {
  return origin?.kind === 'streaming' || origin?.kind === 'streaming_snapshot';
}

export function isTeamMemberOrigin(
  origin: MessageOrigin | undefined,
): origin is Extract<MessageOrigin, { kind: 'team_member' }> {
  return origin?.kind === 'team_member';
}

export function isToolActivityOrigin(origin: MessageOrigin | undefined): boolean {
  return origin?.kind === 'tool_activity';
}

export function ensureOrigin(message: Message): Message & { origin: MessageOrigin } {
  if (message.origin) return message as Message & { origin: MessageOrigin };
  return { ...message, origin: originFromId(message.id, message.role) };
}

import type { Envelope } from './envelope';
import type { UseEnvelopeStreamReturn } from './useEnvelopeStream';
import type { Message } from './types';
import type { Session } from '../session/types';
import { finalizeOrphanToolMessages, toolEventFromMessage } from './envelopeToolCall';
import { patchStreamingMessage } from './streamContentPatch';
import { createMessageBatchWriter } from './messageStoreBatch';
import { shouldSessionWsSkipEnvelope } from './inboundSyncRouting';
import { sessionContextPatchFromEnvelope, isSessionCompressNotice } from './sessionContextPatch';
import type { SessionContextPatch } from './sessionContextPatch';

import { originFromId } from './messageOrigin';
import {
  createStreamingMessageFromActivity,
  patchStreamingMessageFromDelta,
  finalizeStreamingMessageFromDone,
  createToolMessageFromActivityStart,
  mergeToolResultFromDone,
} from './activityMessageAdapter';
import { toolEventToMessage } from './toolEventMarkdown';
import type { ActivityStartMeta, ActivityDeltaMeta, ActivityDoneMeta } from './activityTypes';

export function createPlaceholderMessage(id: string, sessionID: string, role: string, content: string): Message {
  return {
    id,
    session_id: sessionID,
    parent_message_id: '',
    turn_id: '',
    turn_number: 0,
    seq_in_turn: 0,
    role,
    content_markdown: content,
    model_name: 'mock',
    token_in: 0,
    token_out: 0,
    latency_ms: 0,
    status: 'ok',
    attachments_count: 0,
    options_json: '',
    error_message: '',
    created_at: new Date().toISOString(),
    origin: originFromId(id, role),
    agent_ref: null,
    team_member: null,
    source_meta: null,
  };
}

export type StreamHandlerCtx = {
  sessionId: string;
  resolveActiveSessionId: () => string | null;
  getMessages: (sessionId: string) => Message[];
  setMessages: (sessionId: string, rows: Message[]) => void;
  markSendingDone: () => void;
  clearSendingTimeout?: () => void;
  onRunAccepted?: () => void;
  onRunStatus: (env: Envelope) => void;
  onErrorNotify: (message: string) => void;
  onOrchestrationNotice?: (message: string) => void;
  onReloadAfterCompletion: (sessionId: string) => Promise<void>;
  onSessionContextPatch?: (sessionId: string, patch: SessionContextPatch) => void;
  onCompressNotice?: (sessionId: string, prevRatio: number, newRatio: number) => void;
  getSessionMetrics?: (
    sessionId: string,
  ) => Pick<Session, 'total_tokens' | 'max_context_used_ratio' | 'input_tokens' | 'output_tokens'> | undefined;
  onRunActivity?: () => void;
  onFirstByteArrived?: () => void;
  /**
   * Chat-visible execution progress event (orchestration / team / tool /
   * thinking step). Consumers can accumulate these envelopes to drive inline
   * progress cards in the execution progress timeline.
   *
   * See docs/reports/2026-06-10-proposal-execution-progress-inline.md
   */
  onExecutionProgress?: (env: Envelope) => void;
  /** Team-only: resolve member meta for member_* envelopes */
  resolveMemberMeta?: (agentKey: string) => { agent_key: string; name: string; role: string };
  /**
   * H-03: Maximum time (ms) to wait for a runner_completion event after the
   * first streaming event arrives. If exceeded, the streaming session is
   * forcefully finalized to prevent messages from being stuck in 'streaming'
   * status indefinitely. Defaults to 10 minutes if not provided.
   */
  streamTimeoutMs?: number;
  /** Route activity envelopes to timeline handler */
  onActivityEnvelope?: (env: Envelope) => void;
};

function markPendingUserFailed(messages: Message[], pendingId: string, errorMessage: string): Message[] {
  return messages.map((m) =>
    m.id === pendingId
      ? {
          ...m,
          status: 'failed',
          error_message: errorMessage,
        }
      : m,
  );
}

/**
 * Mark all active streaming assistant messages (ws-stream-*) as failed.
 * Called when an error event arrives during streaming, ensuring that
 * in-progress assistant messages don't remain stuck in 'streaming' status.
 */
function markStreamingMessagesFailed(messages: Message[], sessionId: string, errorMessage: string): Message[] {
  return messages.map((m) => {
    if (m.role !== 'assistant' || m.status !== 'streaming') return m;
    if (m.origin?.kind !== 'streaming') return m;
    if (m.session_id !== sessionId) return m;
    return {
      ...m,
      status: 'failed',
      error_message: errorMessage,
    };
  });
}

function latestPendingUserId(messages: Message[]): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    const id = messages[i]?.id ?? '';
    if (id.startsWith('pending-user-')) return id;
  }
  return '';
}

/**
 * AF-GAP-04: Apply team member metadata to a reply Activity message.
 *
 * When the backend ActivityProjector detects a team member author, it sets
 * `Meta: { member_id: <author> }` on the Activity (see OnMemberMessageDelta
 * in internal/agent/activity_projector.go). The envelope builder surfaces
 * this as `metadata.meta.member_id`.
 *
 * This function mirrors the Legacy `member_message_start` handler's message
 * fields so the AF path produces identical team_member / origin / options_json
 * data, enabling the frontend to render member avatars and role badges without
 * relying on the Legacy member_message_* handlers.
 *
 * If `member_id` is absent or `resolveMemberMeta` is unavailable, the message
 * is left unchanged (coordinator or single-agent reply).
 */
function applyMemberMetaToMessage(msg: Message, md: Record<string, unknown>, ctx: StreamHandlerCtx): void {
  const metaObj = md.meta as Record<string, unknown> | undefined;
  const memberId = typeof metaObj?.member_id === 'string' ? metaObj.member_id : '';
  if (!memberId || !ctx.resolveMemberMeta) return;
  const memberMeta = ctx.resolveMemberMeta(memberId);
  msg.model_name = `team/${memberMeta.role || 'member'}`;
  msg.options_json = JSON.stringify({ team_member: memberMeta });
  msg.origin = { kind: 'team_member', agentKey: memberId };
  msg.team_member = { agent_id: '', name: memberMeta.name, role: memberMeta.role };
}

/** Shared streaming row patch for WS handlers and inbound sync. */
export function patchStreamingEnvelope(
  messages: Message[],
  sessionId: string,
  streamId: string,
  env: Envelope,
  isDone: boolean,
): Message[] {
  const cur = messages;
  const exists = cur.some((m) => m.id === streamId);
  let next = cur;
  if (!exists) {
    next = [
      ...cur,
      {
        ...createPlaceholderMessage(streamId, sessionId, 'assistant', ''),
        status: 'streaming',
      },
    ];
  }
  return patchStreamingMessage(next, streamId, {
    text: isDone ? undefined : env.content?.text,
    reasoning: isDone ? undefined : env.content?.reasoning,
    replaceText: isDone ? env.content?.text : undefined,
    replaceReasoning: isDone ? env.content?.reasoning : undefined,
    status: isDone ? 'ok' : 'streaming',
  });
}

function withSessionFilter(
  ctx: StreamHandlerCtx,
  handler: (env: Envelope, sid: string) => void,
): (env: Envelope) => void {
  return (env: Envelope) => {
    if (shouldSessionWsSkipEnvelope(env)) return;
    const sid = env.session_id || ctx.sessionId;
    const active = ctx.resolveActiveSessionId();
    if (sid !== ctx.sessionId || (active && sid !== active)) return;
    handler(env, sid);
  };
}

export function bindStreamHandlers(
  stream: UseEnvelopeStreamReturn,
  ctx: StreamHandlerCtx,
  opts?: { batched?: boolean },
): () => void {
  const batched = opts?.batched ?? false;
  const writer = batched
    ? createMessageBatchWriter(
        () => ctx.getMessages(ctx.sessionId),
        (rows) => ctx.setMessages(ctx.sessionId, rows),
      )
    : null;

  /** Remove the "thinking" placeholder message created on run_status=running.
   * Called when real streaming content (activity_start) arrives. */
  function removeThinkingPlaceholder(sid: string) {
    const msgs = ctx.getMessages(sid);
    const idx = msgs.findIndex((m) => m.id.startsWith('run-') && m.model_name === 'thinking');
    if (idx >= 0) {
      writer?.flushSync();
      const updated = [...msgs];
      updated.splice(idx, 1);
      ctx.setMessages(sid, updated);
    }
  }

  /** AF-correlation: 用后端 Activity 的 turn_id 回填 pending-user 占位消息的 turn_id。
   *
   * pending-user 占位消息创建时 turn_id=''（见 useChatSender.createPlaceholderMessage），
   * 而后端 Activity.TurnID = userMsg.ID（见 chat_orchestrator_durable.go:82,97）。
   * useConversationTimeline 通过 turn_id 将 Activity 记录关联到 UserTurn：
   *   turnId = userMessage?.turn_id || assistantMessage?.turn_id || ''
   * 若 pending-user 的 turn_id 始终为空，则 turnActivities=undefined，agentWork.activities=[]，
   * EventStream 的 v-if="agentWork.activities.length" 不渲染，思考和回复 UI 不显示。
   *
   * 此函数在 activity_start(kind=task) 到达时调用，用 md.turn_id 更新最新的 pending-user
   * 占位消息，使其与 Activity 记录的 turnId 匹配，完成关联闭环。 */
  function backfillPendingUserTurnId(sid: string, turnId: string) {
    if (!turnId) return;
    const msgs = ctx.getMessages(sid);
    const pendingIdx = msgs.findIndex((m) => m.id.startsWith('pending-user-') && m.turn_id === '');
    if (pendingIdx < 0) return;
    writer?.flushSync();
    const updated = [...msgs];
    updated[pendingIdx] = { ...updated[pendingIdx], turn_id: turnId };
    ctx.setMessages(sid, updated);
  }

  // H-03: Stream timeout protection. If runner_completion never arrives
  // (e.g., WS disconnect), force-finalize all streaming/tool_running messages
  // after the timeout expires. The timer starts on the first streaming event
  // and is cleared when runner_completion or error arrives.
  const STREAM_TIMEOUT_MS = ctx.streamTimeoutMs ?? 10 * 60 * 1_000;
  let streamTimeoutId: ReturnType<typeof setTimeout> | null = null;
  let streamStarted = false;

  function startStreamTimeout() {
    if (streamStarted) return;
    streamStarted = true;
    streamTimeoutId = setTimeout(() => {
      const sid = ctx.resolveActiveSessionId() ?? ctx.sessionId;
      if (!sid) return;
      writer?.flushSync();
      let rows = ctx.getMessages(sid);
      // Finalize orphan tool messages
      rows = finalizeOrphanToolMessages(rows, '流式响应超时，已自动结束');
      // Mark streaming assistant messages as failed
      rows = markStreamingMessagesFailed(rows, sid, '流式响应超时，已自动结束');
      ctx.setMessages(sid, rows);
      ctx.markSendingDone();
      ctx.onErrorNotify('流式响应超时，已自动结束');
    }, STREAM_TIMEOUT_MS);
  }

  function clearStreamTimeout() {
    if (streamTimeoutId !== null) {
      clearTimeout(streamTimeoutId);
      streamTimeoutId = null;
    }
  }

  function applySessionContextPatch(sessionId: string, env: Envelope) {
    if (!ctx.onSessionContextPatch && !ctx.onCompressNotice) return;
    const prev = ctx.getSessionMetrics?.(sessionId);
    const patch = sessionContextPatchFromEnvelope(env, prev);
    if (patch) {
      ctx.onSessionContextPatch?.(sessionId, patch);
    }
    if (isSessionCompressNotice(env) && ctx.onCompressNotice) {
      const prevRatio = prev?.max_context_used_ratio ?? 0;
      const newRatio = patch?.context_used_ratio ?? 0;
      ctx.onCompressNotice(sessionId, prevRatio, newRatio);
    }
  }

  stream.onType(
    'context_usage',
    withSessionFilter(ctx, (_env, sid) => {
      applySessionContextPatch(sid, _env);
    }),
  );

  stream.onType('run_status', (env: Envelope) => {
    if (env.session_id && env.session_id !== ctx.sessionId) return;
    ctx.onRunActivity?.();
    ctx.onRunStatus(env);
    const status = String(env.metadata?.status ?? '');
    if (status === 'running' || status === 'accepted') {
      ctx.clearSendingTimeout?.();
      ctx.onRunAccepted?.();

      // Create a placeholder assistant message so the user sees "正在思考"
      // immediately instead of staring at a blank screen during the BUILD
      // phase (0-15s). The placeholder is replaced when the first
      // activity_start arrives.
      const sid = ctx.sessionId;
      const placeholderId = `run-${env.metadata?.run_id ?? 'pending'}`;
      const existing = ctx.getMessages(sid);
      if (!existing.some((m) => m.id === placeholderId)) {
        const placeholder: Message = {
          ...createPlaceholderMessage(placeholderId, sid, 'assistant', ''),
          status: 'streaming',
          model_name: 'thinking',
          origin: { kind: 'streaming', sessionId: sid },
        };
        writer?.flushSync();
        ctx.setMessages(sid, [...existing, placeholder]);
      }
    } else if (status === 'failed' || status === 'cancelled' || status === 'completed') {
      // Remove the thinking placeholder on terminal status.
      // Under normal flow, activity_start already removed it,
      // but guard against edge cases (e.g., empty LLM response).
      removeThinkingPlaceholder(ctx.sessionId);
    }
  });

  // T7.3d: Legacy member_message_start / member_delta / member_message_done
  // handlers removed. Team member messages are now handled exclusively by
  // the AF path: activity_start(kind=reply) with meta.member_id triggers
  // applyMemberMetaToMessage (see case 'reply' below), which sets the same
  // team_member / origin / options_json fields the Legacy handlers did.
  // The Legacy handlers are no longer needed and have been removed to
  // eliminate dual-path rendering bugs.

  stream.onType('intent_pass', (env: Envelope) => {
    const meta = env.metadata as Record<string, unknown> | undefined;
    const kind = typeof meta?.intent_kind === 'string' ? meta.intent_kind : '';
    const target = typeof meta?.target_agent === 'string' ? meta.target_agent : '';
    const parts = ['编排：意图识别'];
    if (kind) parts.push(kind);
    if (target) parts.push(`→ ${target}`);
    ctx.onOrchestrationNotice?.(parts.join(' · '));
  });

  stream.onType('transfer', (env: Envelope) => {
    const from = env.transfer?.from_agent?.trim() ?? '';
    const to = env.transfer?.to_agent?.trim() ?? '';
    if (!from && !to) return;
    ctx.onOrchestrationNotice?.(`编排：正在转接 ${from || '?'} → ${to || '?'}`);
  });

  if (ctx.onExecutionProgress) {
    stream.onType(
      'execution_progress',
      withSessionFilter(ctx, (env) => {
        ctx.onExecutionProgress?.(env);
      }),
    );
  }

  // run_heartbeat touches run activity for stall detection.
  stream.onType(
    'run_heartbeat',
    withSessionFilter(ctx, () => {
      ctx.onRunActivity?.();
    }),
  );

  // === Fallback handlers for raw error/runner_completion envelopes ===
  // In AF mode, the backend wraps errors into activity_start(kind=error) and
  // turn completion into activity_done(kind=task). However, if the backend
  // sends raw error/runner_completion envelopes (e.g., pre-AF fallback or
  // infrastructure errors), these handlers ensure the frontend doesn't get
  // stuck. They are intentionally lightweight — the Activity handlers above
  // handle the full lifecycle.

  stream.onType('runner_completion', async (env: Envelope) => {
    clearStreamTimeout();
    ctx.markSendingDone();
    writer?.flushSync();
    const sid = ctx.resolveActiveSessionId() ?? ctx.sessionId;
    if (!sid) return;
    const finalized = finalizeOrphanToolMessages(ctx.getMessages(sid));
    ctx.setMessages(sid, finalized);
    applySessionContextPatch(sid, env);
    if (shouldSessionWsSkipEnvelope(env)) return;
    try {
      await ctx.onReloadAfterCompletion(sid);
    } catch {
      /* caller may surface errors */
    }
  });

  stream.onType('error', async (env: Envelope) => {
    clearStreamTimeout();
    const errType = env.error?.type ?? '';
    if (errType.startsWith('flow_')) return;
    const msg = env.error?.message ?? 'stream failed';
    ctx.onErrorNotify(msg);
    const sid = ctx.resolveActiveSessionId() ?? ctx.sessionId;
    writer?.flushSync();
    if (sid) {
      let rows = ctx.getMessages(sid);
      const pendingUserId = env.request_id?.startsWith('pending-user-') ? env.request_id : latestPendingUserId(rows);
      if (pendingUserId) {
        rows = markPendingUserFailed(rows, pendingUserId, msg);
      }
      rows = markStreamingMessagesFailed(rows, sid, msg);
      ctx.setMessages(sid, rows);
    }
    ctx.markSendingDone();
    if (sid && !shouldSessionWsSkipEnvelope(env)) {
      try {
        await ctx.onReloadAfterCompletion(sid);
      } catch {
        /* caller may surface errors */
      }
    }
  });

  // === Activity Handlers ===
  // These handlers drive the messageStore via Activity envelopes.

  stream.onType('activity_start', (env: Envelope) => {
    if (shouldSessionWsSkipEnvelope(env)) return;
    const sid = env.session_id || ctx.sessionId;
    const active = ctx.resolveActiveSessionId();
    if (sid !== ctx.sessionId || (active && sid !== active)) return;
    const md = (env.metadata ?? {}) as Record<string, unknown>;
    const kind = String(md.kind ?? '');

    if (kind === 'task') {
      ctx.onRunActivity?.();
      ctx.onFirstByteArrived?.();

      // Remove the placeholder message created on run_status=running.
      // The real streaming message will be created by the Activity handlers below.
      removeThinkingPlaceholder(sid);

      // AF-correlation: 用 md.turn_id 回填 pending-user 占位消息的 turn_id，
      // 使 useConversationTimeline 能将后续 Activity 记录关联到此 UserTurn。
      const turnId = typeof md.turn_id === 'string' ? md.turn_id : '';
      backfillPendingUserTurnId(sid, turnId);
    }

    const rawActivityId = String(md.activity_id ?? '');
    if (!rawActivityId) return; // Guard: activity_id must be present
    const activityId = `actv-${rawActivityId}`;

    switch (kind) {
      case 'thinking': {
        const newMsg = createStreamingMessageFromActivity(activityId, sid, md as unknown as ActivityStartMeta);
        if (writer && sid === ctx.sessionId) {
          writer.insert(newMsg);
        } else {
          const msgs = ctx.getMessages(sid);
          ctx.setMessages(sid, [...msgs, newMsg]);
        }
        startStreamTimeout();
        break;
      }
      case 'reply': {
        const newMsg = createStreamingMessageFromActivity(activityId, sid, md as unknown as ActivityStartMeta);
        // AF-GAP-04: When meta.member_id is present, this reply Activity was
        // produced by a team member (OnMemberMessageDelta/Done on the backend).
        // Apply the same team_member metadata as the Legacy member_message_start
        // handler so the frontend can distinguish member replies from the
        // coordinator's reply (avatar, role badge, options_json).
        applyMemberMetaToMessage(newMsg, md, ctx);
        if (writer && sid === ctx.sessionId) {
          writer.insert(newMsg);
        } else {
          const msgs = ctx.getMessages(sid);
          ctx.setMessages(sid, [...msgs, newMsg]);
        }
        startStreamTimeout();
        ctx.onFirstByteArrived?.();
        break;
      }
      case 'action': {
        const toolMsg = createToolMessageFromActivityStart(sid, md as unknown as ActivityStartMeta);
        if (writer && sid === ctx.sessionId) {
          writer.insert(toolMsg);
        } else {
          const msgs = ctx.getMessages(sid);
          ctx.setMessages(sid, [...msgs, toolMsg]);
        }
        break;
      }
      case 'error': {
        clearStreamTimeout();
        const errMsg = String(md.content ?? 'stream failed');
        const errType = String(md.error_type ?? '');
        if (!errType.startsWith('flow_')) {
          ctx.onErrorNotify?.(errMsg);
          writer?.flushSync();
          const msgs = ctx.getMessages(sid);
          const withFailed = markStreamingMessagesFailed(msgs, sid, errMsg);
          const pendingId = latestPendingUserId(withFailed);
          const final = pendingId ? markPendingUserFailed(withFailed, pendingId, errMsg) : withFailed;
          ctx.setMessages(sid, final);
        }
        ctx.markSendingDone();
        break;
      }
    }

    ctx.onActivityEnvelope?.(env);
  });

  stream.onType('activity_delta', (env: Envelope) => {
    if (shouldSessionWsSkipEnvelope(env)) return;
    const sid = env.session_id || ctx.sessionId;
    const active = ctx.resolveActiveSessionId();
    if (sid !== ctx.sessionId || (active && sid !== active)) return;
    const md = (env.metadata ?? {}) as Record<string, unknown>;
    const field = String(md.delta_field ?? '');
    const chunk = String(md.delta_chunk ?? '');
    if (!chunk) return;

    const rawActivityId = String(md.activity_id ?? '');
    if (!rawActivityId) return; // Guard: activity_id must be present
    const activityId = `actv-${rawActivityId}`;

    ctx.onRunActivity?.();

    if (writer && sid === ctx.sessionId) {
      writer.update(activityId, (cur) => {
        const patched = patchStreamingMessageFromDelta(cur, md as unknown as ActivityDeltaMeta);
        // P2-F1: skip array copy when the patch is a no-op (terminal status
        // or unknown delta_field). patchStreamingMessageFromDelta returns the
        // same reference in those cases.
        if (patched === cur) return undefined;
        return patched;
      });
    } else {
      const msgs = ctx.getMessages(sid);
      const idx = msgs.findIndex((m) => m.id === activityId);
      if (idx >= 0) {
        const patched = patchStreamingMessageFromDelta(msgs[idx], md as unknown as ActivityDeltaMeta);
        // P2-F1: skip array copy + setMessages when the patch is a no-op.
        // Do NOT return early — onActivityEnvelope must still fire below.
        if (patched !== msgs[idx]) {
          const next = [...msgs];
          next[idx] = patched;
          ctx.setMessages(sid, next);
        }
      }
    }

    ctx.onActivityEnvelope?.(env);
  });

  stream.onType('activity_done', async (env: Envelope) => {
    if (shouldSessionWsSkipEnvelope(env)) return;
    const sid = env.session_id || ctx.sessionId;
    const active = ctx.resolveActiveSessionId();
    if (sid !== ctx.sessionId || (active && sid !== active)) return;
    const md = (env.metadata ?? {}) as Record<string, unknown>;
    const kind = String(md.kind ?? '');
    const rawActivityId = String(md.activity_id ?? '');
    const activityId = rawActivityId ? `actv-${rawActivityId}` : '';

    switch (kind) {
      case 'thinking': {
        if (!activityId) break;
        writer?.flushSync();
        const msgs = ctx.getMessages(sid);
        const idx = msgs.findIndex((m) => m.id === activityId);
        if (idx >= 0) {
          const finalized = finalizeStreamingMessageFromDone(msgs[idx], md as unknown as ActivityDoneMeta);
          const next = [...msgs];
          next[idx] = finalized;
          ctx.setMessages(sid, next);
        }
        break;
      }
      case 'reply': {
        if (!activityId) break;
        writer?.flushSync();
        const msgs = ctx.getMessages(sid);
        const idx = msgs.findIndex((m) => m.id === activityId);
        if (idx >= 0) {
          const finalized = finalizeStreamingMessageFromDone(msgs[idx], md as unknown as ActivityDoneMeta);
          const next = [...msgs];
          next[idx] = finalized;
          ctx.setMessages(sid, next);
        }
        break;
      }
      case 'action': {
        const toolCallId = String(md.tool_call_id ?? '');
        const actId = `act-${toolCallId}`;
        if (writer && sid === ctx.sessionId) {
          writer.update(actId, (cur) => {
            const existing = toolEventFromMessage(cur);
            if (!existing) return undefined;
            const merged = mergeToolResultFromDone(existing, md as unknown as ActivityDoneMeta);
            const updated = toolEventToMessage(sid, merged);
            updated.id = actId;
            return { ...cur, ...updated, id: actId };
          });
        } else {
          const msgs = ctx.getMessages(sid);
          const idx = msgs.findIndex((m) => m.id === actId);
          if (idx >= 0) {
            const existing = toolEventFromMessage(msgs[idx]);
            if (existing) {
              const merged = mergeToolResultFromDone(existing, md as unknown as ActivityDoneMeta);
              const updated = toolEventToMessage(sid, merged);
              updated.id = actId;
              const next = [...msgs];
              next[idx] = { ...msgs[idx], ...updated, id: actId };
              ctx.setMessages(sid, next);
            }
          }
        }
        break;
      }
      case 'task': {
        clearStreamTimeout();
        ctx.markSendingDone();
        writer?.flushSync();
        const finalized = finalizeOrphanToolMessages(ctx.getMessages(sid));
        ctx.setMessages(sid, finalized);
        // Apply usage if present
        const usage = md.usage as Record<string, unknown> | undefined;
        if (usage) {
          applySessionContextPatch(sid, env);
        }
        if (shouldSessionWsSkipEnvelope(env)) return;
        try {
          await ctx.onReloadAfterCompletion?.(sid);
        } catch {
          /* caller may surface errors */
        }
        break;
      }
    }

    ctx.onActivityEnvelope?.(env);
  });

  stream.onType('activity_child_start', (env: Envelope) => {
    ctx.onActivityEnvelope?.(env);
  });

  // Return a cleanup function that clears the stream timeout and disposes
  // the batch writer. Callers should invoke this when the stream is
  // disconnected or the component is unmounted to prevent the timeout
  // from firing on stale state or the writer from flushing after unmount.
  return () => {
    clearStreamTimeout();
    writer?.dispose();
  };
}

import { ref } from 'vue';
import { useQuasar } from 'quasar';
import { useRouter } from 'vue-router';
import type { GraphDefinition, GraphVersionInfo } from './types';
import { useGraphStore } from '../../stores/graph';

export function useGraphEditorAssets(graphDef: GraphDefinition, isNew: () => boolean) {
  const $q = useQuasar();
  const router = useRouter();
  const graphStore = useGraphStore();

  const versionDialogOpen = ref(false);
  const versions = ref<GraphVersionInfo[]>([]);
  const versionsLoading = ref(false);
  const rollingBackVersion = ref<number | null>(null);
  const templateDialogOpen = ref(false);
  const templateName = ref('');
  const templateCategory = ref('custom');
  const templateSaving = ref(false);
  const importInputRef = ref<HTMLInputElement | null>(null);

  async function openVersionDialog() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '请先保存 Graph' });
      return;
    }
    versionDialogOpen.value = true;
    versionsLoading.value = true;
    try {
      versions.value = await graphStore.fetchGraphVersions(graphDef.id);
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '加载版本失败' });
    } finally {
      versionsLoading.value = false;
    }
  }

  async function rollbackVersion(version: number, onRestored?: () => Promise<void>) {
    if (!graphDef.id) return;
    rollingBackVersion.value = version;
    try {
      const restored = await graphStore.rollbackGraph(graphDef.id, version);
      Object.assign(graphDef, restored);
      versionDialogOpen.value = false;
      $q.notify({ type: 'positive', message: `已回滚到 v${version}` });
      await onRestored?.();
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '回滚失败' });
    } finally {
      rollingBackVersion.value = null;
    }
  }

  async function exportCurrentGraph() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '请先保存 Graph' });
      return;
    }
    try {
      const result = await graphStore.exportGraphDefinition(graphDef.id);
      const blob = new Blob([result.json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `${graphDef.name || graphDef.id}.graph.json`;
      anchor.click();
      URL.revokeObjectURL(url);
      $q.notify({ type: 'positive', message: 'Graph 已导出' });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '导出失败' });
    }
  }

  function triggerImport() {
    importInputRef.value?.click();
  }

  async function onImportFile(event: Event) {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    try {
      const json = await file.text();
      const created = await graphStore.importGraphDefinition(
        json,
        graphDef.name || file.name.replace(/\.json$/i, ''),
        graphDef.description,
      );
      Object.assign(graphDef, created);
      $q.notify({ type: 'positive', message: 'Graph 已导入' });
      router.replace({ name: 'graph-editor', params: { id: created.id } });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '导入失败' });
    }
  }

  function openTemplateDialog() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '请先保存 Graph' });
      return;
    }
    templateName.value = graphDef.name ? `${graphDef.name} 模板` : '';
    templateCategory.value = 'custom';
    templateDialogOpen.value = true;
  }

  async function saveTemplate() {
    if (!graphDef.id || !templateName.value.trim()) return;
    templateSaving.value = true;
    try {
      await graphStore.saveAsTemplate(
        graphDef.id,
        templateName.value.trim(),
        templateCategory.value,
        graphDef.description,
      );
      templateDialogOpen.value = false;
      $q.notify({ type: 'positive', message: '已保存为用户模板' });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '保存模板失败' });
    } finally {
      templateSaving.value = false;
    }
  }

  return {
    versionDialogOpen,
    versions,
    versionsLoading,
    rollingBackVersion,
    templateDialogOpen,
    templateName,
    templateCategory,
    templateSaving,
    importInputRef,
    openVersionDialog,
    rollbackVersion,
    exportCurrentGraph,
    triggerImport,
    onImportFile,
    openTemplateDialog,
    saveTemplate,
  };
}

import { computed, ref, watch } from 'vue';
import type { Ref } from 'vue';
import type { GraphDefinition, ValidationError, ValidationWarning } from './types';

export function useGraphLocalValidation(graphDef: Ref<GraphDefinition>) {
  const cycleWarnings = ref<ValidationWarning[]>([]);

  const localErrors = computed<ValidationError[]>(() => {
    const errors: ValidationError[] = [];
    const def = graphDef.value;
    const nodeIds = new Set(def.nodes.map((n) => n.id));

    cycleWarnings.value = [];

    if (def.nodes.length === 0) return errors;

    if (!def.entryPoint) {
      errors.push({ code: 'no_entry_point', nodeId: '', field: 'entryPoint', message: '缺少入口节点' });
    } else if (!nodeIds.has(def.entryPoint)) {
      errors.push({ code: 'no_entry_point', nodeId: def.entryPoint, field: 'entryPoint', message: '入口节点不存在' });
    }

    const seen = new Map<string, number>();
    for (const n of def.nodes) {
      const prev = seen.get(n.id);
      if (prev !== undefined) {
        errors.push({ code: 'duplicate_node', nodeId: n.id, field: 'id', message: `节点 ID 重复: ${n.id}` });
      } else {
        seen.set(n.id, 1);
      }
    }

    for (const e of def.edges) {
      if (!nodeIds.has(e.from)) {
        errors.push({ code: 'edge_source_missing', nodeId: '', field: 'from', message: `边源节点不存在: ${e.from}` });
      }
      if (!nodeIds.has(e.to)) {
        errors.push({ code: 'edge_target_missing', nodeId: e.from, field: 'to', message: `边目标节点不存在: ${e.to}` });
      }
    }
    for (const ce of def.conditionalEdges) {
      if (!nodeIds.has(ce.from)) {
        errors.push({
          code: 'edge_source_missing',
          nodeId: '',
          field: 'from',
          message: `条件边源节点不存在: ${ce.from}`,
        });
        continue;
      }
      const targets = Object.values(ce.pathMap ?? {});
      for (const t of targets) {
        if (!nodeIds.has(t)) {
          errors.push({
            code: 'edge_target_missing',
            nodeId: ce.from,
            field: 'pathMap',
            message: `条件边目标节点不存在: ${t}`,
          });
        }
      }
    }

    if (def.entryPoint && nodeIds.has(def.entryPoint)) {
      const reachable = new Set<string>();
      const queue = [def.entryPoint];
      while (queue.length > 0) {
        const cur = queue.pop()!;
        if (reachable.has(cur)) continue;
        reachable.add(cur);
        for (const e of def.edges) {
          if (e.from === cur && !reachable.has(e.to)) queue.push(e.to);
        }
        for (const ce of def.conditionalEdges) {
          if (ce.from === cur) {
            for (const t of Object.values(ce.pathMap ?? {})) {
              if (!reachable.has(t)) queue.push(t);
            }
          }
        }
      }
      for (const n of def.nodes) {
        if (!reachable.has(n.id)) {
          errors.push({ code: 'unreachable_node', nodeId: n.id, field: '', message: `节点不可达: ${n.id}` });
        }
      }
    }

    const unconditionalAdj = new Map<string, string[]>();
    const fullAdj = new Map<string, string[]>();
    for (const e of def.edges) {
      const ul = unconditionalAdj.get(e.from) ?? [];
      ul.push(e.to);
      unconditionalAdj.set(e.from, ul);
      const fl = fullAdj.get(e.from) ?? [];
      fl.push(e.to);
      fullAdj.set(e.from, fl);
    }
    for (const ce of def.conditionalEdges) {
      const fl = fullAdj.get(ce.from) ?? [];
      for (const t of Object.values(ce.pathMap ?? {})) fl.push(t);
      fullAdj.set(ce.from, fl);
    }

    const cycleVisited = new Set<string>();
    const cycleRecStack = new Set<string>();
    function hasCycleIn(adj: Map<string, string[]>, nodeId: string): boolean {
      cycleVisited.add(nodeId);
      cycleRecStack.add(nodeId);
      for (const neighbor of adj.get(nodeId) ?? []) {
        if (!cycleVisited.has(neighbor)) {
          if (hasCycleIn(adj, neighbor)) return true;
        } else if (cycleRecStack.has(neighbor)) {
          return true;
        }
      }
      cycleRecStack.delete(nodeId);
      return false;
    }

    let hasUnconditionalCycle = false;
    const uv = new Set<string>();
    for (const n of def.nodes) {
      if (!uv.has(n.id)) {
        cycleVisited.clear();
        cycleRecStack.clear();
        if (hasCycleIn(unconditionalAdj, n.id)) {
          hasUnconditionalCycle = true;
          break;
        }
        for (const v of cycleVisited) uv.add(v);
      }
    }
    if (hasUnconditionalCycle) {
      errors.push({ code: 'loop_no_exit', nodeId: '', field: '', message: '图中存在无条件循环（死循环）' });
    } else {
      let hasConditionalCycle = false;
      const cv = new Set<string>();
      for (const n of def.nodes) {
        if (!cv.has(n.id)) {
          cycleVisited.clear();
          cycleRecStack.clear();
          if (hasCycleIn(fullAdj, n.id)) {
            hasConditionalCycle = true;
            break;
          }
          for (const v of cycleVisited) cv.add(v);
        }
      }
      if (hasConditionalCycle) {
        cycleWarnings.value.push({
          code: 'conditional_loop',
          nodeId: '',
          field: '',
          message: '图中存在条件循环（运行时可能回退）',
        });
      }
    }

    return errors;
  });

  const localWarnings = computed<ValidationWarning[]>(() => {
    const warnings: ValidationWarning[] = [];
    const def = graphDef.value;

    const connectedNodes = new Set<string>();
    for (const e of def.edges) {
      connectedNodes.add(e.from);
      connectedNodes.add(e.to);
    }
    for (const ce of def.conditionalEdges) {
      connectedNodes.add(ce.from);
      for (const t of Object.values(ce.pathMap ?? {})) connectedNodes.add(t);
    }
    if (def.entryPoint) connectedNodes.add(def.entryPoint);
    if (def.finishPoint) connectedNodes.add(def.finishPoint);

    for (const n of def.nodes) {
      if (!connectedNodes.has(n.id)) {
        warnings.push({ code: 'orphan_node', nodeId: n.id, field: '', message: `孤立节点（无连接）: ${n.id}` });
      }
    }

    warnings.push(...cycleWarnings.value);

    return warnings;
  });

  const localValid = computed(() => localErrors.value.length === 0);

  return { localErrors, localWarnings, localValid };
}

import { asRecord, pickI32, pickNum, pickStr } from '../../shared/wireJson';

/** @deprecated Use mapCollection from features/knowledge/api.ts instead — this type omits description/workspace/updated_at. */
export type KnowledgeCollectionRow = {
  id: string;
  name: string;
  embedding_model: string;
  dim: number;
  status: string;
  document_count: number;
  chunk_count: number;
  created_at: string;
};

/** @deprecated Use mapCollection from features/knowledge/api.ts instead. */
export function mapCollection(raw: unknown): KnowledgeCollectionRow {
  const r = asRecord(raw);
  return {
    id: pickStr(r, 'id', 'id'),
    name: pickStr(r, 'name', 'name'),
    embedding_model: pickStr(r, 'embedding_model', 'embeddingModel'),
    dim: pickI32(r, 'dim', 'dim'),
    status: pickStr(r, 'status', 'status'),
    document_count: pickI32(r, 'document_count', 'documentCount'),
    chunk_count: pickI32(r, 'chunk_count', 'chunkCount'),
    created_at: pickStr(r, 'created_at', 'createdAt'),
  };
}

import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useQuasar } from 'quasar';
import axios from 'axios';
import { hasIndexingDocuments } from './knowledgeUi';
import type { KnowledgeChunk, KnowledgeDocument, EmbedderConfig, UpdateEmbedderConfigInput } from './types';
import { useKnowledgeStore } from '../../stores/knowledge';
import { useKnowledgeIngestWs } from './useKnowledgeIngestWs';

export function useKnowledgePage() {
  const $q = useQuasar();
  const knowledgeStore = useKnowledgeStore();
  const selectedId = ref('');
  const docsLoading = ref(false);
  const error = ref('');
  const unavailable = ref('');
  const tab = ref('documents');
  const createOpen = ref(false);
  const createLoading = ref(false);
  const ingestOpen = ref(false);
  const ingestLoading = ref(false);
  const ingestFile = ref<File | null>(null);
  const searchQuery = ref('');
  const searchTopK = ref(5);
  const searchMinScore = ref(0);
  const searchHybridMode = ref('auto');
  const searchRewriteStrategy = ref('');
  const searchUseRerank = ref(false);
  const searchResults = ref<KnowledgeChunk[]>([]);
  const searchLoading = ref(false);
  const searchRan = ref(false);
  const embedderSaving = ref(false);
  const createForm = ref({ name: '', description: '', embedding_model: 'text-embedding-3-small' });
  const ingestForm = ref({
    source: '',
    mime_type: 'text/plain',
    text: '',
    fileContentBase64: '',
    chunk_strategy: '',
    chunk_size: 0,
    chunk_overlap: 0,
  });

  const embedderConfig = computed<EmbedderConfig | null>(() => knowledgeStore.embedderConfig);
  const collections = computed(() => knowledgeStore.collections);
  const loading = computed(() => knowledgeStore.loading);
  const documents = computed(() => knowledgeStore.documentsByCollection[selectedId.value] ?? []);
  const selectedCollection = computed(() => collections.value.find((c) => c.id === selectedId.value));
  const docSourceMap = computed(() => {
    const map: Record<string, string> = {};
    for (const d of documents.value) {
      map[d.id] = d.source;
    }
    return map;
  });

  useKnowledgeIngestWs(
    () => (hasIndexingDocuments(documents.value) ? selectedId.value : ''),
    () => {
      void loadDocuments();
      void loadCollections();
    },
  );

  function friendlyError(err: unknown): string {
    if (axios.isAxiosError(err)) {
      const status = err.response?.status;
      if (status === 404) {
        return '知识库 API 未找到 (404)。请确认：① 页面使用 http://localhost:9001/knowledge（勿直接打开 :8000）；② 已重启 admin（go run ./cmd/admin）；③ 请求路径为 /v1/knowledge/... 而非 /api/v1/...。';
      }
      if (!err.response && (err.code === 'ERR_NETWORK' || err.message === 'Network Error')) {
        return '无法连接后端。请确认 admin 在 :8000 运行，并通过 http://localhost:9001 打开页面。';
      }
      const data = err.response?.data as { message?: string } | undefined;
      if (typeof data?.message === 'string' && data.message.trim()) {
        return data.message;
      }
    }
    const msg = err instanceof Error ? err.message : String(err);
    if (/unavailable|pgvector|postgres|not configured/i.test(msg)) {
      unavailable.value = msg;
      return '';
    }
    return msg;
  }

  async function loadCollections() {
    error.value = '';
    unavailable.value = '';
    try {
      const res = await knowledgeStore.loadCollections({ limit: 100 });
      if (!selectedId.value && res.items.length) {
        selectedId.value = res.items[0].id;
      }
    } catch (e) {
      error.value = friendlyError(e) || '加载集合失败';
    }
  }

  async function loadDocuments() {
    if (!selectedId.value) return;
    docsLoading.value = true;
    try {
      await knowledgeStore.loadDocuments(selectedId.value, { limit: 100 });
    } catch (e) {
      $q.notify({ type: 'negative', message: friendlyError(e) || '加载文档失败' });
    } finally {
      docsLoading.value = false;
    }
  }

  function selectCollection(id: string) {
    selectedId.value = id;
    tab.value = 'documents';
  }

  function openCreateCollection() {
    createForm.value = { name: '', description: '', embedding_model: 'text-embedding-3-small' };
    createOpen.value = true;
  }

  async function submitCreateCollection() {
    if (!createForm.value.name.trim()) {
      $q.notify({ type: 'warning', message: '请填写名称' });
      return;
    }
    createLoading.value = true;
    try {
      const col = await knowledgeStore.addCollection({
        name: createForm.value.name.trim(),
        description: createForm.value.description.trim(),
        embedding_model: createForm.value.embedding_model.trim(),
      });
      createOpen.value = false;
      await loadCollections();
      selectedId.value = col.id;
      $q.notify({ type: 'positive', message: '集合已创建' });
    } catch (e) {
      $q.notify({ type: 'negative', message: friendlyError(e) || '创建失败' });
    } finally {
      createLoading.value = false;
    }
  }

  function confirmDeleteCollection() {
    const col = selectedCollection.value;
    if (!col) return;
    $q.dialog({
      title: '删除集合',
      message: `确定删除「${col.name}」及其全部文档？`,
      cancel: true,
      persistent: true,
    }).onOk(() => void deleteCollectionConfirmed(col.id));
  }

  async function deleteCollectionConfirmed(id: string) {
    try {
      await knowledgeStore.removeCollection(id);
      if (selectedId.value === id) {
        selectedId.value = '';
      }
      await loadCollections();
      $q.notify({ type: 'positive', message: '已删除' });
    } catch (e) {
      $q.notify({ type: 'negative', message: friendlyError(e) || '删除失败' });
    }
  }

  // DAT-04 / KB-01 helpers: byte-faithful base64 for both file uploads (any
  // binary format) and pasted text (UTF-8). Prior code went through
  // FileReader.readAsText, which mangled non-ASCII / binary payloads.
  function bytesToBase64(bytes: Uint8Array): string {
    const CHUNK = 0x8000;
    let binary = '';
    for (let i = 0; i < bytes.length; i += CHUNK) {
      const slice = bytes.subarray(i, Math.min(i + CHUNK, bytes.length));
      binary += String.fromCharCode.apply(null, slice as unknown as number[]);
    }
    return btoa(binary);
  }

  function utf8ToBase64(str: string): string {
    return bytesToBase64(new TextEncoder().encode(str));
  }

  // REV-D: mirrors backend extractSupportedMimes — keep in sync with
  // internal/service/knowledge.go:extractSupportedMimes.
  const EXTRACT_SUPPORTED_MIMES = new Set([
    'text/plain',
    'text/markdown',
    'text/csv',
    'text/html',
    'text/xml',
    'application/json',
    'application/xml',
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  ]);

  function isExtractSupported(mimeType: string): boolean {
    const m = mimeType.trim().toLowerCase();
    return EXTRACT_SUPPORTED_MIMES.has(m) || m.startsWith('text/');
  }

  function inferMime(file: File): string {
    if (file.type && file.type.trim()) return file.type;
    const lower = file.name.toLowerCase();
    if (lower.endsWith('.md')) return 'text/markdown';
    if (lower.endsWith('.txt') || lower.endsWith('.log')) return 'text/plain';
    if (lower.endsWith('.json')) return 'application/json';
    if (lower.endsWith('.csv')) return 'text/csv';
    if (lower.endsWith('.html') || lower.endsWith('.htm')) return 'text/html';
    if (lower.endsWith('.xml')) return 'application/xml';
    if (lower.endsWith('.yaml') || lower.endsWith('.yml')) return 'text/yaml';
    if (lower.endsWith('.toml')) return 'text/toml';
    if (lower.endsWith('.pdf')) return 'application/pdf';
    if (lower.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    if (lower.endsWith('.doc')) return 'application/msword';
    if (lower.endsWith('.pptx')) return 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
    if (lower.endsWith('.xlsx')) return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    // TODO(debt): image MIME removed until OCR is implemented on the backend.
    return 'application/octet-stream';
  }

  function onIngestFile(file: File | File[] | null) {
    const picked = Array.isArray(file) ? file[0] : file;
    ingestForm.value.fileContentBase64 = '';
    if (!picked) {
      ingestFile.value = null;
      return;
    }
    ingestFile.value = picked;
    ingestForm.value.source = ingestForm.value.source || picked.name;
    const inferred = inferMime(picked);
    ingestForm.value.mime_type = inferred;
    const reader = new FileReader();
    // ArrayBuffer keeps binary payloads (PDF/DOCX/…) intact; we still surface a
    // textarea preview for text-like MIME so the user can review before submit.
    reader.onload = () => {
      const buf = reader.result as ArrayBuffer | null;
      if (!buf) return;
      const bytes = new Uint8Array(buf);
      ingestForm.value.fileContentBase64 = bytesToBase64(bytes);
      const textLike = /^text\//i.test(inferred) || inferred === 'application/json' || inferred === 'application/xml';
      if (textLike) {
        try {
          ingestForm.value.text = new TextDecoder('utf-8', { fatal: false }).decode(buf);
        } catch {
          ingestForm.value.text = '';
        }
      } else {
        ingestForm.value.text = '';
      }
    };
    reader.readAsArrayBuffer(picked);
  }

  async function submitIngest() {
    if (!selectedId.value) return;
    const fileBase64 = ingestForm.value.fileContentBase64;
    const text = ingestForm.value.text.trim();
    if (!fileBase64 && !text) {
      $q.notify({ type: 'warning', message: '请提供文件或文本内容' });
      return;
    }
    ingestLoading.value = true;
    try {
      // Prefer pre-encoded file base64 (binary-safe); fall back to UTF-8 text encoding.
      const b64 = fileBase64 || utf8ToBase64(text);
      await knowledgeStore.ingest({
        collection_id: selectedId.value,
        source: ingestForm.value.source || 'upload',
        mime_type: ingestForm.value.mime_type || 'text/plain',
        content_base64: b64,
        chunk_strategy: ingestForm.value.chunk_strategy || undefined,
        chunk_size: ingestForm.value.chunk_size || undefined,
        chunk_overlap: ingestForm.value.chunk_overlap || undefined,
      });
      ingestOpen.value = false;
      const submittedMime = ingestForm.value.mime_type || 'text/plain';
      ingestForm.value = {
        source: '',
        mime_type: 'text/plain',
        text: '',
        fileContentBase64: '',
        chunk_strategy: '',
        chunk_size: 0,
        chunk_overlap: 0,
      };
      ingestFile.value = null;
      await loadDocuments();
      await loadCollections();
      // REV-D: binary formats that require server-side extraction get a softer
      // success message so users know search availability depends on parsing.
      if (isExtractSupported(submittedMime)) {
        $q.notify({ type: 'positive', message: '文档已提交入库，正在后台解析...' });
      } else {
        $q.notify({
          type: 'warning',
          message: `文档已上传（${submittedMime}），但当前后端可能不支持解析该格式，检索内容可能为空。`,
          timeout: 8000,
        });
      }
    } catch (e) {
      $q.notify({ type: 'negative', message: friendlyError(e) || '入库失败' });
    } finally {
      ingestLoading.value = false;
    }
  }

  function confirmDeleteDocument(doc: KnowledgeDocument) {
    $q.dialog({
      title: '删除文档',
      message: `删除「${doc.source}」？`,
      cancel: true,
    }).onOk(async () => {
      try {
        await knowledgeStore.removeDocument(doc.id, selectedId.value);
        await loadDocuments();
        await loadCollections();
        $q.notify({ type: 'positive', message: '已删除' });
      } catch (e) {
        $q.notify({ type: 'negative', message: friendlyError(e) || '删除失败' });
      }
    });
  }

  async function runSearch() {
    if (!selectedId.value || !searchQuery.value.trim()) return;
    searchLoading.value = true;
    searchRan.value = true;
    try {
      searchResults.value = await knowledgeStore.search({
        collection_id: selectedId.value,
        query: searchQuery.value.trim(),
        top_k: searchTopK.value,
        min_score: searchMinScore.value || undefined,
        hybrid_search: searchHybridMode.value || undefined,
        rewrite_strategy: searchRewriteStrategy.value || undefined,
        use_rerank: searchUseRerank.value ? true : undefined,
      });
    } catch (e) {
      $q.notify({ type: 'negative', message: friendlyError(e) || '检索失败' });
    } finally {
      searchLoading.value = false;
    }
  }

  let docPollTimer: ReturnType<typeof setInterval> | null = null;

  function stopDocPoll() {
    if (docPollTimer) {
      clearInterval(docPollTimer);
      docPollTimer = null;
    }
  }

  function syncDocPoll() {
    stopDocPoll();
    if (!selectedId.value || tab.value !== 'documents' || !hasIndexingDocuments(documents.value)) return;
    docPollTimer = setInterval(() => {
      if (!selectedId.value || !hasIndexingDocuments(documents.value)) {
        stopDocPoll();
        return;
      }
      void loadDocuments();
      void loadCollections();
    }, 3000);
  }

  watch(selectedId, (id) => {
    if (id) void loadDocuments();
  });

  watch(
    () => [documents.value.map((d) => d.status).join(','), tab.value, selectedId.value] as const,
    () => syncDocPoll(),
  );

  onUnmounted(stopDocPoll);

  async function saveEmbedderConfig(input: UpdateEmbedderConfigInput) {
    embedderSaving.value = true;
    try {
      await knowledgeStore.saveEmbedderConfig(input);
      $q.notify({ type: 'positive', message: 'Embedder 配置已保存' });
    } catch (e) {
      $q.notify({ type: 'negative', message: e instanceof Error ? e.message : '保存失败' });
    } finally {
      embedderSaving.value = false;
    }
  }

  async function loadEmbedderConfig() {
    try {
      await knowledgeStore.loadEmbedderConfig();
    } catch (e) {
      $q.notify({ type: 'warning', message: 'Embedder 配置加载失败，检索功能可能不可用' });
    }
  }

  return {
    collections,
    selectedId,
    selectedCollection,
    documents,
    docSourceMap,
    loading,
    docsLoading,
    error,
    unavailable,
    tab,
    createOpen,
    createLoading,
    ingestOpen,
    ingestLoading,
    ingestFile,
    searchQuery,
    searchTopK,
    searchMinScore,
    searchHybridMode,
    searchRewriteStrategy,
    searchUseRerank,
    searchResults,
    searchLoading,
    searchRan,
    createForm,
    ingestForm,
    embedderConfig,
    embedderSaving,
    saveEmbedderConfig,
    loadCollections,
    loadDocuments,
    loadEmbedderConfig,
    selectCollection,
    openCreateCollection,
    submitCreateCollection,
    confirmDeleteCollection,
    onIngestFile,
    submitIngest,
    confirmDeleteDocument,
    runSearch,
  };
}

